import { useEffect, useMemo, useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Empty, Field, InlineStatus, Modal, Pill, SectionHead } from '../components/ui';
import { CAPABILITIES, FUNCTIONAL_TYPES, PROVIDER_PRESETS, PROTOCOLS, capabilityLabel, emptyProvider, protocolLabel } from '../lib/providers';
import { vault } from '../lib/vault';
import { OUTCOME_LABELS } from '../lib/adapter';
import { apiFetch, runConnectionTest } from '../lib/apiClient';
import type { Capability, ProviderConfig, TestResult } from '../lib/types';

interface DraftState {
  draft: ProviderConfig;
  apiKey: string;
  paramsText: string;
  hasStoredKey: boolean;
  presetWarning: string;
}

function makeState(p?: ProviderConfig): DraftState {
  const draft = p ? { ...p, endpoints: { ...p.endpoints }, capabilities: [...p.capabilities] } : emptyProvider();
  return {
    draft,
    apiKey: '',
    paramsText: JSON.stringify(draft.requestParams ?? {}, null, 2),
    hasStoredKey: vault.hasSecret(draft.id),
    presetWarning: '',
  };
}

const ENDPOINT_FIELDS: Array<{ key: keyof ProviderConfig['endpoints']; label: string; hint: string }> = [
  { key: 'chat', label: 'Chat 端点', hint: '文本对话路径' },
  { key: 'models', label: 'Models 端点', hint: '可选' },
  { key: 'test', label: '测试端点', hint: '生成类协议建议显式配置一个无副作用的健康检查地址' },
  { key: 'videoCreate', label: '视频创建端点', hint: '异步任务创建' },
  { key: 'videoQuery', label: '任务查询端点', hint: '按 task_id 查询' },
  { key: 'image', label: '图片生成端点', hint: '可选' },
  { key: 'tts', label: 'TTS 端点', hint: '可选' },
  { key: 'voices', label: '声音档案端点', hint: '可选' },
];

export function Providers(): JSX.Element {
  const { providers, saveProviders, vaultUnlocked, vaultExists, navigate, me, apiOnline, refreshVault } = useApp();
  const [editing, setEditing] = useState<string | null | undefined>(undefined); // undefined=closed, null=new
  const [state, setState] = useState<DraftState>(() => makeState());
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<{ text: string; tone: 'muted' | 'ok' | 'err' | 'warn' }>({ text: '', tone: 'muted' });
  const [testingId, setTestingId] = useState<string | null>(null);
  const [lastBody, setLastBody] = useState('');
  const [billableProbe, setBillableProbe] = useState(false);
  const [presetOpen, setPresetOpen] = useState(false);

  useEffect(() => {
    void refreshVault();
  }, [refreshVault]);

  const storedIds = useMemo(() => (vaultUnlocked ? vault.storedProviderIds : []), [vaultUnlocked, providers]);

  const openNew = (presetId?: string) => {
    const preset = PROVIDER_PRESETS.find((p) => p.id === presetId);
    const base = emptyProvider(preset?.config ?? {});
    if (preset) base.capabilities = [...(preset.config.capabilities ?? [])];
    const s = makeState(base);
    s.presetWarning = preset?.warning ?? '';
    s.hasStoredKey = false;
    setState(s);
    setEditing(null);
    setStatus({ text: '', tone: 'muted' });
    setLastBody('');
    setPresetOpen(false);
  };

  const openEdit = (p: ProviderConfig) => {
    setState(makeState(p));
    setEditing(p.id);
    setStatus({ text: '', tone: 'muted' });
    setLastBody('');
  };

  const patch = (next: Partial<ProviderConfig>) => setState((s) => ({ ...s, draft: { ...s.draft, ...next } }));

  const toggleCapability = (id: Capability) =>
    setState((s) => ({
      ...s,
      draft: {
        ...s.draft,
        capabilities: s.draft.capabilities.includes(id)
          ? s.draft.capabilities.filter((c) => c !== id)
          : [...s.draft.capabilities, id],
      },
    }));

  const save = async () => {
    const { draft, apiKey, paramsText } = state;
    if (!draft.name.trim()) return setStatus({ text: '请填写 Provider 名称。', tone: 'err' });
    if (!draft.baseUrl.trim()) return setStatus({ text: '请填写 API Base URL（系统不会为你猜测地址）。', tone: 'err' });
    let params: Record<string, unknown>;
    try {
      params = JSON.parse(paramsText || '{}') as Record<string, unknown>;
      if (!params || typeof params !== 'object' || Array.isArray(params)) throw new Error('必须是对象');
    } catch {
      return setStatus({ text: '请求参数必须是合法的 JSON 对象。', tone: 'err' });
    }
    if (apiKey && !vaultUnlocked) return setStatus({ text: '保存密钥需要先解锁保险库。', tone: 'err' });

    setBusy(true);
    try {
      if (apiKey) await vault.setSecret(draft.id, { apiKey });
      const next: ProviderConfig = { ...draft, requestParams: params, updatedAt: new Date().toISOString() };
      const exists = providers.some((p) => p.id === next.id);
      await saveProviders(exists ? providers.map((p) => (p.id === next.id ? next : p)) : [next, ...providers]);

      // Cloud sync is optional and only attempted for a signed-in identity.
      if (apiOnline && me && !me.isGuest) {
        try {
          await apiFetch(`/providers/${next.id}`, {
            method: 'PUT',
            body: JSON.stringify({ ...next, capabilities: next.capabilities }),
          });
          setStatus({ text: '已保存，并同步到你的云端工作空间（仅元数据，不含密钥）。', tone: 'ok' });
        } catch (e) {
          setStatus({ text: `本机已保存；云端同步失败：${e instanceof Error ? e.message : '未知错误'}`, tone: 'warn' });
        }
      } else {
        setStatus({ text: '已保存到本机。云端同步需要登录；本次未上传任何密钥。', tone: 'ok' });
      }
      setState((s) => ({ ...s, hasStoredKey: vault.hasSecret(draft.id), apiKey: '' }));
      setEditing(undefined);
      await refreshVault();
    } catch (e) {
      setStatus({ text: e instanceof Error ? e.message : '保存失败', tone: 'err' });
    } finally {
      setBusy(false);
    }
  };

  const remove = async (p: ProviderConfig) => {
    if (vaultUnlocked && vault.hasSecret(p.id)) await vault.removeSecret(p.id);
    await saveProviders(providers.filter((x) => x.id !== p.id));
    await refreshVault();
    setStatus({ text: `已删除 ${p.name} 的配置${vaultUnlocked ? '及本机密钥' : '（保险库锁定，密钥请解锁后单独删除）'}。`, tone: 'ok' });
  };

  const test = async (p: ProviderConfig) => {
    if (!vaultUnlocked || !vault.hasSecret(p.id)) {
      setStatus({ text: '测试连接需要先创建并解锁保险库，且该 Provider 必须已保存 API Key。', tone: 'warn' });
      navigate('vault');
      return;
    }
    setTestingId(p.id);
    setLastBody('');
    setStatus({ text: `正在向 ${p.baseUrl} 发送真实请求…`, tone: 'muted' });
    try {
      const secret = vault.getSecret(p.id);
      if (!secret) throw new Error('密钥不可用');
      const { result, upstreamBody } = await runConnectionTest(p, secret.apiKey, { allowBillableProbe: billableProbe });
      await saveProviders(providers.map((x) => (x.id === p.id ? { ...x, lastTest: result } : x)));
      setLastBody(upstreamBody ?? '');
      setStatus({
        text: `${p.name}：${result.label}${result.httpStatus ? ` (HTTP ${result.httpStatus})` : ''} — ${result.detail}`,
        tone: result.code === 'CONNECTION_OK' ? 'ok' : result.code === 'NOT_TESTABLE' ? 'warn' : 'err',
      });
    } catch (e) {
      setStatus({ text: e instanceof Error ? e.message : '测试失败', tone: 'err' });
    } finally {
      setTestingId(null);
    }
  };

  return (
    <>
      <div className="page-head">
        <div className="eyebrow">Configuration / Bring Your Own Key</div>
        <h1 className="page-title display">我的 AI 模型</h1>
        <p className="page-lede">
          每个 Provider 独立配置 Base URL、协议、Model ID、能力与端点。能力必须显式声明——系统不会因为模型名称里有 “Video” 就认为它能生成视频，也不会假设所有 OpenAI 兼容接口完全一致。
        </p>
      </div>

      {!vaultExists ? (
        <Callout>
          <strong>还没有密钥保险库。</strong> 请先在「密钥保险库」创建密码，之后才能保存 API Key 并运行真实连接测试。
          <Button size="sm" variant="primary" style={{ marginLeft: 12 }} onClick={() => navigate('vault')}>去创建</Button>
        </Callout>
      ) : !vaultUnlocked ? (
        <Callout>
          <strong>保险库已锁定。</strong> 已保存的 Key 仍在，但需要输入密码解锁后才能用于测试连接或生成调用。
          <Button size="sm" style={{ marginLeft: 12 }} onClick={() => navigate('vault')}>去解锁</Button>
        </Callout>
      ) : null}

      <SectionHead num="01" title="已配置的 Provider" aside={`${providers.length} 条 · 密钥 ${storedIds.length} 条（仅存本机）`} />

      <div style={{ display: 'flex', gap: 9, marginBottom: 18, flexWrap: 'wrap' }}>
        <Button variant="primary" onClick={() => setPresetOpen(true)}>+ 新增 Provider</Button>
        <Button onClick={() => openNew()}>从空白开始</Button>
        <label className="check" style={{ marginLeft: 'auto' }}>
          <input type="checkbox" checked={billableProbe} onChange={(e) => setBillableProbe(e.target.checked)} />
          <span>允许真实生成探测<small>仅在你提供 createBodyTemplate 时生效，可能产生上游费用</small></span>
        </label>
      </div>

      {providers.length === 0 ? (
        <Empty
          title="没有配置任何模型"
          desc="SOL AI 不内置任何人的 API Key。从下面选择一个预设开始，或完全自定义。B.AI 预设故意留空——在拿到官方开发者文档前，系统不会猜测地址、模型 ID 或端点。"
          action={<Button variant="primary" size="sm" onClick={() => setPresetOpen(true)}>选择预设</Button>}
        />
      ) : (
        <div>
          {providers.map((p) => (
            <div className="row" key={p.id} style={{ alignItems: 'flex-start', paddingTop: 18, paddingBottom: 18 }}>
              <div className="row-main">
                <div className="row-name">
                  {p.name}
                  {p.enabled ? <Pill tone="accent">{p.functionalType}</Pill> : <Pill>已停用</Pill>}
                  <TestPill result={p.lastTest} />
                </div>
                <div className="row-meta">{p.baseUrl || '(未填写 Base URL)'} · {p.modelId || '(未填写 Model ID)'} · {protocolLabel(p.protocol)} · {p.timeoutMs}ms</div>
                <div style={{ marginTop: 8, display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                  {p.capabilities.length === 0 ? (
                    <span className="faint" style={{ fontSize: 10.5 }}>未标注任何能力</span>
                  ) : (
                    p.capabilities.map((c) => <span className="pill" key={c}>{capabilityLabel(c)}</span>)
                  )}
                </div>
                {p.lastTest ? (
                  <div style={{ fontSize: 10.5, color: 'var(--ink-faint)', marginTop: 8 }}>
                    {new Date(p.lastTest.testedAt).toLocaleString('zh-CN')} · {p.lastTest.realUpstreamCall ? '已发起真实上游请求' : '未发起上游请求'} · {p.lastTest.detail}
                  </div>
                ) : null}
              </div>
              <div className="row-actions" style={{ flexDirection: 'column', alignItems: 'flex-end', gap: 6 }}>
                <div style={{ display: 'flex', gap: 8 }}>
                  <Button size="sm" variant="primary" disabled={testingId === p.id} onClick={() => void test(p)}>
                    {testingId === p.id ? '测试中…' : '测试连接'}
                  </Button>
                  <Button size="sm" onClick={() => openEdit(p)}>编辑</Button>
                  <Button size="sm" variant="danger" onClick={() => void remove(p)}>删除</Button>
                </div>
                {vaultUnlocked && vault.hasSecret(p.id) ? <span className="faint" style={{ fontSize: 10 }}>本机已存 Key</span> : <span className="faint" style={{ fontSize: 10 }}>无本机 Key</span>}
              </div>
            </div>
          ))}
        </div>
      )}

      {status.text ? <InlineStatus text={status.text} tone={status.tone} /> : null}
      {lastBody ? <div className="result-box">上游响应（已脱敏，截断至 2000 字符）：{'\n'}{lastBody || '(空响应体)'}</div> : null}

      <div className="notice">
        测试连接会向上游发送真实请求，不做“非空即成功”的假判断。结果分类：{Object.values(OUTCOME_LABELS).join(' / ')}。
        密钥只用于本次请求，不写入任何持久化存储；响应与错误信息在展示前脱敏。
        使用 Worker 代理时，代理不持久化密钥、不记录日志；静态站点直连时受上游 CORS 策略限制，
        失败会明确报「直连失败」，不会误判为 Key 无效。可在「设置 → 服务连接」调整调用方式。
      </div>

      {/* Preset picker */}
      {presetOpen ? (
        <Modal title="选择 Provider 预设" sub="预填项仅采用公开可核实的官方文档；未核实的服务一律留空。" onClose={() => setPresetOpen(false)}>
          {PROVIDER_PRESETS.map((preset) => (
            <div className="row" key={preset.id} style={{ alignItems: 'flex-start' }}>
              <div className="row-main">
                <div className="row-name">
                  {preset.label}
                  {preset.verified ? <Pill tone="ok">文档已核实</Pill> : <Pill tone="warn">待核实 · 字段留空</Pill>}
                </div>
                <div className="row-meta" style={{ whiteSpace: 'normal' }}>{preset.description}</div>
                {preset.warning ? <div style={{ fontSize: 11, color: 'var(--warn)', marginTop: 8, lineHeight: 1.7 }}>{preset.warning}</div> : null}
              </div>
              <div className="row-actions"><Button size="sm" onClick={() => openNew(preset.id)}>使用</Button></div>
            </div>
          ))}
        </Modal>
      ) : null}

      {/* Editor */}
      {editing !== undefined ? (
        <Modal
          title={editing === null ? '新增 Provider' : '编辑 Provider'}
          sub="API Key 只在解锁状态下写入本机加密保险库，不会进入普通存储或服务器。"
          onClose={() => setEditing(undefined)}
          footer={
            <>
              <Button onClick={() => setEditing(undefined)}>取消</Button>
              <Button variant="primary" disabled={busy} onClick={() => void save()}>{busy ? '保存中…' : '保存配置'}</Button>
            </>
          }
        >
          {state.presetWarning ? <Callout><strong>注意：</strong>{state.presetWarning}</Callout> : null}

          <div className="grid-2" style={{ gap: '0 16px' }}>
            <Field label="Provider 名称"><input className="input" value={state.draft.name} onChange={(e) => patch({ name: e.target.value })} placeholder="例如 B.AI Opus" /></Field>
            <Field label="API 协议" hint="不同协议使用不同适配器">
              <select className="select" value={state.draft.protocol} onChange={(e) => patch({ protocol: e.target.value as ProviderConfig['protocol'] })}>
                {PROTOCOLS.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
              </select>
            </Field>
          </div>

          <Field label="API Base URL" hint="系统不会猜测 / 推断地址">
            <input className="input mono" value={state.draft.baseUrl} onChange={(e) => patch({ baseUrl: e.target.value })} placeholder="https://your-provider.example/v1" />
          </Field>

          <div className="grid-2" style={{ gap: '0 16px' }}>
            <Field label="Model ID" hint="必须真实存在"><input className="input mono" value={state.draft.modelId} onChange={(e) => patch({ modelId: e.target.value })} placeholder="由服务商文档确认" /></Field>
            <Field label="功能类型">
              <select className="select" value={state.draft.functionalType} onChange={(e) => patch({ functionalType: e.target.value as ProviderConfig['functionalType'] })}>
                {FUNCTIONAL_TYPES.map((f) => <option key={f.id} value={f.id}>{f.label}</option>)}
              </select>
            </Field>
          </div>

          <Field label="模型能力" hint="逐项显式声明，不根据名称推断">
            <div className="check-grid">
              {CAPABILITIES.map((c) => (
                <label className="check" key={c.id}>
                  <input type="checkbox" checked={state.draft.capabilities.includes(c.id)} onChange={() => toggleCapability(c.id)} />
                  <span><span className="mono">{c.label}</span><small>{c.note}</small></span>
                </label>
              ))}
            </div>
          </Field>

          <div className="divider" />
          <div className="eyebrow" style={{ marginBottom: 14 }}>Endpoints · 端点路径</div>
          <div className="grid-2" style={{ gap: '0 16px' }}>
            {ENDPOINT_FIELDS.map((f) => (
              <Field key={f.key} label={f.label} hint={f.hint}>
                <input
                  className="input mono"
                  value={state.draft.endpoints[f.key] ?? ''}
                  onChange={(e) => patch({ endpoints: { ...state.draft.endpoints, [f.key]: e.target.value } })}
                  placeholder="/path"
                />
              </Field>
            ))}
          </div>

          <Field label="请求参数（JSON 对象）" hint="会合并进真实请求体；生成类协议可放 createBodyTemplate">
            <textarea className="textarea" rows={4} value={state.paramsText} onChange={(e) => setState((s) => ({ ...s, paramsText: e.target.value }))} />
          </Field>

          <div className="grid-2" style={{ gap: '0 16px' }}>
            <Field label="超时（毫秒）"><input className="input mono" type="number" min={1000} max={120000} value={state.draft.timeoutMs} onChange={(e) => patch({ timeoutMs: Number(e.target.value) })} /></Field>
            <Field label="状态"><label className="check"><input type="checkbox" checked={state.draft.enabled} onChange={(e) => patch({ enabled: e.target.checked })} /><span>启用该 Provider</span></label></Field>
          </div>

          <div className="divider" />
          <div className="eyebrow" style={{ marginBottom: 12 }}>API Key · 敏感信息</div>
          {!vaultUnlocked ? (
            <Callout neutral>
              保险库未解锁，无法写入或读取密钥。你可以先保存不含 Key 的配置，之后再到「密钥保险库」解锁并补填。
              <Button size="sm" style={{ marginLeft: 10 }} onClick={() => navigate('vault')}>去解锁</Button>
            </Callout>
          ) : null}
          <Field
            label="API Key"
            hint={state.hasStoredKey ? '已存有密钥；留空则保持不变' : '输入后加密保存到本机'}
          >
            <input
              className="input mono"
              type="password"
              autoComplete="off"
              disabled={!vaultUnlocked}
              value={state.apiKey}
              onChange={(e) => setState((s) => ({ ...s, apiKey: e.target.value }))}
              placeholder={state.hasStoredKey ? '••••••••••••（已保存，留空不修改）' : 'sk-… 或你的服务商密钥'}
            />
          </Field>
          <div className="faint" style={{ fontSize: 10.5, lineHeight: 1.8 }}>
            密钥使用 Web Crypto（PBKDF2-SHA256 / AES-256-GCM）加密后存入 IndexedDB；明文只存在于解锁期间的内存中。
            浏览器本地加密不是绝对安全，请勿在不受信任的设备上使用。
          </div>

          <Field label="备注"><textarea className="textarea" rows={2} value={state.draft.notes ?? ''} onChange={(e) => patch({ notes: e.target.value })} placeholder="接口文档链接、权限说明等" /></Field>

          {status.text ? <InlineStatus text={status.text} tone={status.tone} /> : null}
        </Modal>
      ) : null}
    </>
  );
}

function TestPill({ result }: { result?: TestResult | null }): JSX.Element {
  if (!result) return <Pill tone="warn">未测试</Pill>;
  if (result.code === 'CONNECTION_OK') return <Pill tone="ok">连接成功</Pill>;
  if (result.code === 'NOT_TESTABLE') return <Pill tone="warn">未执行测试</Pill>;
  return <Pill tone="err">{result.label}</Pill>;
}
