/**
 * Client for the SOL AI API + upstream provider calls.
 *
 * The API key is attached ONLY to the single outbound proxy envelope (or, in
 * explicit direct mode, to the single upstream request). It is never placed in
 * a URL, never cached, never persisted, and never sent to any other endpoint.
 *
 * Deployment note: ai.solyoung.top is a STATIC site, so a same-origin Worker
 * may not exist. `proxyRequest` therefore:
 *   - prefers the Worker (same origin or configured external origin),
 *   - and, in `auto` mode, falls back to a direct browser->upstream request
 *     ONLY when the Worker itself was unreachable. An upstream error response
 *     is NEVER retried through another path (that could double-charge).
 */

import type { Identity, ProviderConfig, ProxyEnvelope, ProxyResponse, TestResult } from './types';
import { buildTestPlan, redactSecrets, toTestResult } from './adapter';
import { apiUrl, getRuntimeConfig } from './runtime';

const SESSION_KEY = 'sol-ai:session';
const MAX_BODY_BYTES = 512_000;

export function setSessionToken(token: string | null): void {
  try {
    if (token) sessionStorage.setItem(SESSION_KEY, token);
    else sessionStorage.removeItem(SESSION_KEY);
  } catch {
    /* private mode */
  }
}

function sessionToken(): string | null {
  try {
    return sessionStorage.getItem(SESSION_KEY);
  } catch {
    return null;
  }
}

export class ApiError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message);
    this.name = 'ApiError';
  }
}

async function parseJson<T>(res: Response): Promise<T> {
  const text = await res.text();
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new ApiError(res.status, `Invalid JSON from API (HTTP ${res.status})`);
  }
}

export async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const token = sessionToken();
  let res: Response;
  try {
    res = await fetch(apiUrl(path), {
      ...init,
      headers: {
        'content-type': 'application/json',
        ...(token ? { authorization: `Bearer ${token}` } : {}),
        ...(init.headers as Record<string, string> | undefined),
      },
    });
  } catch (e) {
    throw new ApiError(0, `无法连接 Worker：${e instanceof Error ? e.message : String(e)}`);
  }
  const data = await parseJson<Record<string, unknown>>(res);
  if (!res.ok) throw new ApiError(res.status, String(data.error ?? `HTTP ${res.status}`));
  return data as T;
}

export async function getMe(): Promise<Identity> {
  return apiFetch<Identity>('/me');
}

function looksLikeProxyResponse(value: unknown): value is ProxyResponse {
  if (!value || typeof value !== 'object') return false;
  const v = value as Record<string, unknown>;
  return typeof v.status === 'number' && typeof v.body === 'string' && typeof v.ok === 'boolean';
}

/** Returns null ONLY when the Worker itself is unreachable / not a Worker response. */
async function fetchViaWorker(envelope: ProxyEnvelope): Promise<ProxyResponse | null> {
  try {
    const res = await fetch(apiUrl('/proxy'), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(envelope),
    });
    const text = await res.text();
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      return null; // static host returned HTML / 404 page: there is no Worker here
    }
    if (!looksLikeProxyResponse(parsed)) return null;
    return { ...parsed, transport: 'worker' };
  } catch {
    return null; // network / CORS failure reaching the Worker
  }
}

function envelopeSecrets(envelope: ProxyEnvelope): string[] {
  const secrets: string[] = [];
  for (const [name, value] of Object.entries(envelope.headers ?? {})) {
    if (/^(content-type|anthropic-version|accept)$/i.test(name)) continue;
    const bare = value.replace(/^Bearer\s+/i, '').trim();
    if (bare.length >= 6) secrets.push(bare);
    if (value.length >= 6) secrets.push(value);
  }
  return secrets;
}

function emptyResponse(transportError: string, elapsedMs: number, transport: 'worker' | 'direct'): ProxyResponse {
  return {
    ok: false,
    status: 0,
    statusText: '',
    headers: {},
    body: '',
    elapsedMs,
    truncated: false,
    transportError,
    transport,
  };
}

/**
 * Direct browser -> upstream request. Used on static deployments where no
 * Worker is available. Subject to the upstream's CORS policy; a CORS failure
 * is reported as a transport error, NEVER as "connection successful" and
 * NEVER as "invalid key".
 */
export async function directRequest(envelope: ProxyEnvelope): Promise<ProxyResponse> {
  const started = performance.now();
  const timeout = Math.min(Math.max(envelope.timeoutMs || 60_000, 1_000), 120_000);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  const secrets = envelopeSecrets(envelope);

  try {
    const res = await fetch(envelope.url, {
      method: envelope.method,
      headers: envelope.headers,
      ...(envelope.body === undefined ? {} : { body: envelope.body }),
      signal: controller.signal,
      // Do not send ambient credentials; the key is in the explicit header.
      credentials: 'omit',
      referrerPolicy: 'no-referrer',
    });
    clearTimeout(timer);
    const raw = await res.text();
    const truncated = raw.length > MAX_BODY_BYTES;
    const headers: Record<string, string> = {};
    res.headers.forEach((value, key) => {
      headers[key] = redactSecrets(value, secrets);
    });
    return {
      ok: res.ok,
      status: res.status,
      statusText: res.statusText,
      headers,
      body: redactSecrets(raw.slice(0, MAX_BODY_BYTES), secrets),
      elapsedMs: Math.round(performance.now() - started),
      truncated,
      transport: 'direct',
    };
  } catch (error) {
    clearTimeout(timer);
    const reason = error instanceof Error ? error.message : String(error);
    const timedOut = /abort|timeout/i.test(reason);
    return emptyResponse(
      timedOut
        ? `浏览器直连上游超时。请勿直接重试创建任务，先查询原任务状态，避免重复扣费。`
        : `浏览器直连上游失败：${reason}。常见原因是上游未开放 CORS 预检（authorization / x-api-key 头触发 preflight），或网络/DNS 被拦截。这不代表 Key 无效，也不代表模型不存在；若要通过服务端代理调用，请在设置中填写 Worker 地址并切换为「仅 Worker 代理」。`,
      Math.round(performance.now() - started),
      'direct',
    );
  }
}

/** The one and only outbound path for provider calls. */
export async function proxyRequest(envelope: ProxyEnvelope): Promise<ProxyResponse> {
  const { callMode } = getRuntimeConfig();
  if (callMode === 'direct') return directRequest(envelope);

  const viaWorker = await fetchViaWorker(envelope);
  // A real Worker response — including an upstream error — is final. Retrying
  // it through another path could create a second billable upstream call.
  if (viaWorker) return viaWorker;

  if (callMode === 'worker') {
    return emptyResponse(
      'Worker 代理不可达。当前设置为「仅 Worker 代理」，因此没有向上游发送任何请求。请检查设置中的 API 服务地址，或切换为自动/直连模式。',
      0,
      'worker',
    );
  }
  return directRequest(envelope);
}

/** Real connection test. Returns NOT_TESTABLE (never a fake success) when no safe endpoint exists. */
export async function runConnectionTest(
  config: ProviderConfig,
  apiKey: string,
  opts: { allowBillableProbe?: boolean } = {},
): Promise<{ result: TestResult; note: string; upstreamBody?: string }> {
  const plan = buildTestPlan(config, apiKey, opts);
  if (plan.kind === 'not-testable') {
    return {
      result: {
        code: 'NOT_TESTABLE',
        label: '未执行测试',
        detail: plan.reason,
        testedAt: new Date().toISOString(),
        realUpstreamCall: false,
      },
      note: '未向上游发送任何请求。',
    };
  }
  const response = await proxyRequest(plan.envelope);
  const transportNote =
    response.transport === 'direct'
      ? '\n本次为浏览器直连上游（静态站点无 Worker，或已选择直连）：请求未经 SOL AI 服务端，受上游 CORS 策略约束。'
      : response.transport === 'worker'
        ? '\n本次经 Worker 代理转发，代理不持久化密钥、不记录日志。'
        : '';
  const note = plan.note + transportNote;
  return {
    result: toTestResult(response, note),
    note,
    // Already sanitized (Worker redaction or local redactSecrets); truncate for display.
    upstreamBody: response.body.slice(0, 2000),
  };
}
