import type { ButtonHTMLAttributes, ReactNode } from 'react';

type Variant = 'default' | 'primary' | 'ghost' | 'danger';

export function Button({
  variant = 'default',
  size,
  className = '',
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant; size?: 'sm' | 'lg' }): JSX.Element {
  const cls = [
    'btn',
    variant !== 'default' ? `btn-${variant}` : '',
    size ? `btn-${size}` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');
  return <button className={cls} {...rest} />;
}

export function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: ReactNode;
  children: ReactNode;
}): JSX.Element {
  return (
    <label className="field">
      <span className="field-label">
        <span>{label}</span>
        {hint ? <span className="field-hint">{hint}</span> : null}
      </span>
      {children}
    </label>
  );
}

export function Modal({
  title,
  sub,
  onClose,
  children,
  footer,
}: {
  title: string;
  sub?: ReactNode;
  onClose: () => void;
  children: ReactNode;
  footer?: ReactNode;
}): JSX.Element {
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal" role="dialog" aria-modal="true" aria-label={title}>
        <div className="modal-head">
          <div>
            <div className="modal-title">{title}</div>
            {sub ? <div className="modal-sub">{sub}</div> : null}
          </div>
          <button className="modal-close" onClick={onClose} aria-label="Close">
            ×
          </button>
        </div>
        <div className="modal-body">{children}</div>
        {footer ? <div className="modal-foot">{footer}</div> : null}
      </div>
    </div>
  );
}

export function SectionHead({ num, title, aside }: { num: string; title: string; aside?: ReactNode }): JSX.Element {
  return (
    <div className="section-head">
      <h2 className="section-title">
        <span className="num">{num}</span>
        {title}
      </h2>
      {aside ? <div className="section-aside">{aside}</div> : null}
    </div>
  );
}

export function Empty({
  title,
  desc,
  action,
}: {
  title: string;
  desc: string;
  action?: ReactNode;
}): JSX.Element {
  return (
    <div className="empty">
      <div className="empty-title">{title}</div>
      <p className="empty-desc">{desc}</p>
      {action}
    </div>
  );
}

export function Pill({ tone = '', children }: { tone?: '' | 'ok' | 'warn' | 'err' | 'accent'; children: ReactNode }): JSX.Element {
  return <span className={`pill ${tone}`}>{children}</span>;
}

export function Callout({ children, neutral = false }: { children: ReactNode; neutral?: boolean }): JSX.Element {
  return <div className={`callout ${neutral ? 'neutral' : ''}`}>{children}</div>;
}

/** Small inline action feedback used instead of pretending a background job succeeded. */
export function InlineStatus({ text, tone = 'muted' }: { text: string; tone?: 'muted' | 'ok' | 'err' | 'warn' }): JSX.Element {
  const color = tone === 'ok' ? 'var(--ok)' : tone === 'err' ? 'var(--err)' : tone === 'warn' ? 'var(--warn)' : 'var(--ink-soft)';
  return <div style={{ fontSize: 11.5, color, marginTop: 10, lineHeight: 1.8 }}>{text}</div>;
}
