/**
 * Pluggable tool registry for the Work Agent (v1).
 *
 * Every tool here is REAL and locally executable: it reads/writes actual
 * IndexedDB data or returns actual runtime facts. There are no stub tools,
 * no simulated web search, no fake "code execution", no placeholder results.
 *
 * Tools are deliberately independent of any vendor's `tool_calling` format.
 * The agent uses SOL AI's own structured action protocol, so OpenAI-compatible,
 * Anthropic and custom HTTP providers all work with the same loop.
 *
 * Adding a tool: append a ToolDef to TOOL_REGISTRY. The engine and prompt
 * catalogue pick it up automatically — no changes to the loop required.
 */

import {
  listArtifacts,
  listSessions,
  putArtifact,
  getArtifact,
  removeArtifact,
} from './agentStore';
import type { AgentSession, ArtifactFormat } from './agentTypes';

export interface ToolContext {
  session: AgentSession;
  /** Real number of configured providers in this browser. */
  providerCount: number;
}

export interface ToolResult {
  ok: boolean;
  /** Fed back to the model verbatim. Must not contain secrets. */
  output: string;
}

export interface ToolArgSpec {
  name: string;
  type: 'string' | 'number' | 'boolean';
  required: boolean;
  note: string;
}

export interface ToolDef {
  id: string;
  title: string;
  description: string;
  args: readonly ToolArgSpec[];
  run: (ctx: ToolContext, args: Record<string, unknown>) => Promise<ToolResult>;
}

const MAX_ARTIFACT_CHARS = 200_000;
const MAX_TOOL_OUTPUT_CHARS = 20_000;

const FORMATS: readonly ArtifactFormat[] = ['markdown', 'json', 'text'];

function truncate(text: string, limit = MAX_TOOL_OUTPUT_CHARS): string {
  if (text.length <= limit) return text;
  return `${text.slice(0, limit)}\n…（已截断，原文共 ${text.length} 字符）`;
}

export interface ArgValidation {
  ok: boolean;
  error?: string;
  cleaned: Record<string, unknown>;
}

/** Strict, whitelist-based validation. Unknown keys are dropped, never trusted. */
export function validateToolArgs(tool: ToolDef, raw: Record<string, unknown>): ArgValidation {
  const cleaned: Record<string, unknown> = {};
  const source = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  for (const spec of tool.args) {
    const value = source[spec.name];
    if (value === undefined || value === null || value === '') {
      if (spec.required) return { ok: false, error: `缺少必填参数 ${spec.name}（${spec.note}）`, cleaned: {} };
      continue;
    }
    if (spec.type === 'string') {
      if (typeof value !== 'string') return { ok: false, error: `参数 ${spec.name} 必须是字符串`, cleaned: {} };
      cleaned[spec.name] = value;
    } else if (spec.type === 'number') {
      const n = typeof value === 'number' ? value : Number(value);
      if (!Number.isFinite(n)) return { ok: false, error: `参数 ${spec.name} 必须是数字`, cleaned: {} };
      cleaned[spec.name] = n;
    } else {
      if (typeof value !== 'boolean') return { ok: false, error: `参数 ${spec.name} 必须是布尔值`, cleaned: {} };
      cleaned[spec.name] = value;
    }
  }
  return { ok: true, cleaned };
}

export const TOOL_REGISTRY: readonly ToolDef[] = [
  {
    id: 'artifact.write',
    title: '写入产物',
    description: '把一份交付物保存为具名文件（Markdown / JSON / 纯文本），用户可在会话中查看并下载。重复同名会覆盖。',
    args: [
      { name: 'name', type: 'string', required: true, note: '文件名，如 report.md；只允许字母数字 . _ -' },
      { name: 'content', type: 'string', required: true, note: '文件完整内容' },
      { name: 'format', type: 'string', required: false, note: 'markdown | json | text，默认 markdown' },
    ],
    run: async (ctx, args) => {
      const name = String(args.name);
      const content = String(args.content);
      const format = (args.format ? String(args.format) : 'markdown') as ArtifactFormat;
      if (!FORMATS.includes(format)) return { ok: false, output: `不支持的格式 ${format}，只能是 markdown / json / text。` };
      if (content.length > MAX_ARTIFACT_CHARS) {
        return { ok: false, output: `内容过长（${content.length} 字符），上限 ${MAX_ARTIFACT_CHARS} 字符。请分段写入。` };
      }
      if (format === 'json') {
        try {
          JSON.parse(content);
        } catch (e) {
          return { ok: false, output: `format=json 但内容不是合法 JSON：${e instanceof Error ? e.message : String(e)}` };
        }
      }
      const saved = await putArtifact(ctx.session.id, name, content, format);
      return {
        ok: true,
        output: `已保存产物 ${saved.name}（${saved.format}，${content.length} 字符，session ${ctx.session.id}）。用户可在会话里查看和下载。`,
      };
    },
  },
  {
    id: 'artifact.read',
    title: '读取产物',
    description: '读取当前会话里已有的产物内容，用于继续修改或引用。',
    args: [{ name: 'name', type: 'string', required: true, note: '产物文件名' }],
    run: async (ctx, args) => {
      const found = await getArtifact(ctx.session.id, String(args.name));
      if (!found) return { ok: false, output: `当前会话没有名为 ${String(args.name)} 的产物。可先用 artifact.list 查看。` };
      return { ok: true, output: `产物 ${found.name}（${found.format}，更新于 ${found.updatedAt}）：\n${truncate(found.content)}` };
    },
  },
  {
    id: 'artifact.list',
    title: '列出产物',
    description: '列出当前会话中所有真实存在的产物。',
    args: [],
    run: async (ctx) => {
      const items = await listArtifacts(ctx.session.id);
      if (items.length === 0) return { ok: true, output: '当前会话还没有任何产物。' };
      return {
        ok: true,
        output: `当前会话共 ${items.length} 个产物：\n${items
          .map((a) => `- ${a.name} · ${a.format} · ${a.content.length} 字符 · ${a.updatedAt}`)
          .join('\n')}`,
      };
    },
  },
  {
    id: 'artifact.delete',
    title: '删除产物',
    description: '删除当前会话中的某个产物，不可恢复。',
    args: [{ name: 'name', type: 'string', required: true, note: '产物文件名' }],
    run: async (ctx, args) => {
      const removed = await removeArtifact(ctx.session.id, String(args.name));
      return { ok: removed, output: removed ? `已删除产物 ${String(args.name)}。` : `没有找到产物 ${String(args.name)}，未做任何改动。` };
    },
  },
  {
    id: 'workspace.overview',
    title: '工作区概览',
    description: '返回本机的真实统计：会话数、已配置模型数、产物数、当前会话执行步数。',
    args: [],
    run: async (ctx) => {
      const [sessions, artifacts] = await Promise.all([listSessions(), listArtifacts()]);
      return {
        ok: true,
        output:
          `会话总数 ${sessions.length} · 已配置模型 ${ctx.providerCount} 个 · ` +
          `当前会话产物 ${artifacts.filter((a) => a.sessionId === ctx.session.id).length} 个 · ` +
          `当前会话已执行 ${ctx.session.steps.length} 步 / 上限 ${ctx.session.maxSteps} 步 · ` +
          `会话状态 ${ctx.session.state}。`,
      };
    },
  },
  {
    id: 'clock.now',
    title: '当前时间',
    description: '返回浏览器所在时区的真实当前时间（ISO 8601 与本地时间）。',
    args: [],
    run: async () => {
      const now = new Date();
      return { ok: true, output: `ISO: ${now.toISOString()} · 本地: ${now.toLocaleString('zh-CN')} · 时区偏移(分钟): ${now.getTimezoneOffset()}` };
    },
  },
] as const;

export const TOOL_IDS: readonly string[] = TOOL_REGISTRY.map((t) => t.id);

export function getTool(id: string): ToolDef | undefined {
  return TOOL_REGISTRY.find((t) => t.id === id);
}

/** Injected into the system prompt. Generated from the registry, never hand-maintained. */
export function toolCatalogForPrompt(): string {
  return TOOL_REGISTRY.map((t) => {
    const args = t.args.length
      ? t.args.map((a) => `${a.name}:${a.type}${a.required ? '' : '?'}`).join(', ')
      : '(无参数)';
    return `- ${t.id}(${args}) — ${t.description}`;
  }).join('\n');
}

/** Single entry point used by the engine. Never throws; failures become tool results. */
export async function runTool(
  id: string,
  ctx: ToolContext,
  rawArgs: Record<string, unknown>,
): Promise<ToolResult> {
  const tool = getTool(id);
  if (!tool) {
    return { ok: false, output: `未知工具 ${id}。可用工具：${TOOL_IDS.join(', ')}。请改用列表中的工具，或直接给出 final。` };
  }
  const validation = validateToolArgs(tool, rawArgs);
  if (!validation.ok) return { ok: false, output: `工具参数校验失败：${validation.error}` };
  try {
    return await tool.run(ctx, validation.cleaned);
  } catch (e) {
    return { ok: false, output: `工具执行失败：${e instanceof Error ? e.message : String(e)}` };
  }
}
