import { useEffect, useState } from 'react';
import { useApp } from '../state/AppContext';
import { Button, Callout, Field, InlineStatus, Pill, SectionHead } from '../components/ui';
import { apiFetch } from '../lib/apiClient';
import { CALL_MODE_LABELS, type CallMode } from '../lib/runtime';
import { DEFAULT_MAX_STEPS, AGENT_PROTOCOL_VERSION } from '../lib/agentTypes';
import { TOOL_REGISTRY } from '../lib/tools';

interface Health {
  ok: boolean;
  product: string;
  service: string;
  version: string;
  time: string;
}

interface AuthReport {
  activeAdapter: string;
  note: string;
  providers: Array<{ id: string; configured: boolean; note: string }>;
}

const TIERS = [
  { id: 'free', name: 'Free', projects: '3', storage: '1 GB', team: '1', concurrency: '1' },
  { id: 'creator', name: 'Creator', projects: '30', storage: '50 GB', team: '2', concurrency: '3' },
  { id: 'pro', name: 'Pro', projects: '200', storage: '250 GB', team: '5', concurrency: '8' },
  { id: 'studio', name: 'Studio', projects: '不限', storage: '不限', team: '50', concurrency: '30' },
] as const;

const MODES: CallMode[] = ['auto', 'worker', 'direct'];

export function Settings(): JSX.Element {
  const { theme, setTheme, apiOnline, me, providers, sessions, vaultExists, storageError, runtime, setRuntime } = useApp();
  const [health, setHealth] = useState<Health | null>(null);
  const [auth, setAuth] = useState<AuthReport | null>(null);
  const [error, setError] = useState('');
  const [apiBaseInput, setApiBaseInput] = useState(runtime.apiBase);
  const [mode, setMode] = useState<CallMode>(runtime.callMode);
  const [runtimeMsg, setRuntimeMsg] = useState<{ text: string; tone: 'muted' | 'ok' | 'err' | 'warn' }>({ text: '', tone: 'muted' });

  useEffect(() => {
    setApiBaseInput(runtime.apiBase);
    setMode(runtime.callMode);
  }, [runtime]);

  const check = async () => {
    setError('');
    try {
      const [h, a] = await Promise.all([apiFetch<Health>('/health'), apiFetch<AuthReport>('/auth/providers')]);
      setHealth(h);
      setAuth(a);
    } catch (e) {
      setHealth(null);
      setAuth(null);
      setError(e instanceof Error ? e.message : 'Worker 不可达');
    }
  };

  const saveRuntime = () => {
    try {
      setRuntime({ apiBase: apiBaseInput, callMode: mode });
      setRuntimeMsg({
        text: `已保存。当前：${CALL_MODE_LABELS[mode]}；${apiBaseInput.trim() ? `Worker 地址 ${apiBaseInput.trim()}` : 'Worker 使用本站同源 /api'}。`,
        tone: 'ok',
      });
    } catch (e) {
      setRuntimeMsg({ text: e instanceof Error ? e.message : '保存失败', tone: 'err' });
    }
  };

  return (
    <>
      <div className="page-head">
        <h1 className="page-title display">设置</h1>
        <p className="page-lede">外观、服务连接、Agent 运行环境与权限结构。第一版不开发支付与订阅，但预留了完整的等级与配额字段。</p>
      </div>

      {storageError ? (
        <Callout>
          <strong>本机存储不可用：</strong>{storageError}。界面仍可浏览，但会话、产物与加密密钥无法保存在此浏览器。
          请检查隐私模式、站点存储权限或浏览器扩展设置。
        </Callout>
      ) : null}

      <SectionHead num="01" title="外观" aside="Appearance" />
      <div className="grid-2" style={{ marginBottom: 36 }}>
        <div className="tool-card" style={{ minHeight: 0 }}>
          <div className="tool-card-title" style={{ fontSize: 16, margin: '0 0 6px' }}>配色主题</div>
          <div className="tool-card-desc">近白 / 近黑的单一灰阶，发丝线分隔，无渐变与装饰色。深色模式为纯黑底。</div>
          <div className="tool-card-foot">
            <Pill>{theme === 'light' ? 'LIGHT' : 'DARK'}</Pill>
            <div style={{ display: 'flex', gap: 8 }}>
              <Button size="sm" variant={theme === 'light' ? 'primary' : 'default'} onClick={() => setTheme('light')}>浅色</Button>
              <Button size="sm" variant={theme === 'dark' ? 'primary' : 'default'} onClick={() => setTheme('dark')}>深色</Button>
            </div>
          </div>
        </div>
        <div className="tool-card" style={{ minHeight: 0 }}>
          <div className="tool-card-title" style={{ fontSize: 16, margin: '0 0 6px' }}>字体与排版</div>
          <div className="tool-card-desc mono" style={{ fontSize: 10.5, lineHeight: 2 }}>
            system-ui / -apple-system / sans-serif<br />无外部字体请求，无远程资源依赖
          </div>
          <div className="tool-card-foot"><Pill>SOL AI</Pill><span className="faint" style={{ fontSize: 10.5 }}>单列 · 大留白</span></div>
        </div>
      </div>

      <SectionHead num="02" title="服务连接" aside="Static deployment" />
      <Callout neutral>
        <strong>ai.solyoung.top 是纯静态部署。</strong>页面由 GitHub Pages 提供，同源没有 Cloudflare Worker。
        密钥保险库、模型配置、会话与产物全部留在本机浏览器，不依赖服务器；云端同步、登录与
        服务端代理需要单独部署 Worker 后，在下方填写它的地址。
      </Callout>
      <div style={{ marginTop: 20, maxWidth: 620 }}>
        <Field label="Worker API 服务地址" hint="留空 = 本站同源 /api">
          <input
            className="input"
            value={apiBaseInput}
            onChange={(e) => setApiBaseInput(e.target.value)}
            placeholder="https://sol-ai.example.workers.dev"
            spellCheck={false}
            autoComplete="off"
          />
        </Field>
        <div className="field">
          <span className="field-label"><span>上游调用方式</span><span className="field-hint">决定 API Key 如何送达服务商</span></span>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 2 }}>
            {MODES.map((m) => (
              <Button key={m} size="sm" variant={mode === m ? 'primary' : 'default'} onClick={() => setMode(m)}>
                {CALL_MODE_LABELS[m]}
              </Button>
            ))}
          </div>
        </div>
        <div style={{ display: 'flex', gap: 9, alignItems: 'center', flexWrap: 'wrap' }}>
          <Button variant="primary" onClick={saveRuntime}>保存连接设置</Button>
          <Pill tone={apiOnline ? 'ok' : 'warn'}>{apiOnline ? 'WORKER ONLINE' : 'WORKER OFFLINE'}</Pill>
        </div>
        {runtimeMsg.text ? <InlineStatus text={runtimeMsg.text} tone={runtimeMsg.tone} /> : null}
      </div>
      <div style={{ marginTop: 28 }}>
        <Callout>
          <strong>直连模式的风险，请先看清楚。</strong>选择「自动」或「仅浏览器直连」时，解锁后的 API Key
        会由浏览器直接发给你配置的上游服务商，不经过 SOL AI 服务器；服务端代理的 SSRF 防护与统一脱敏
        由上游 CORS 策略取代。多数接口需要预检允许 authorization / x-api-key 头，若上游不允许，运行会
        明确报「直连失败」，<strong>不会伪装成连接成功，也不会误判为 Key 无效</strong>。任何模式下，
        密钥都不会写入 localStorage、日志或 URL，且 Worker 已真实响应过的错误绝不会换一条路径重试。
        </Callout>
      </div>

      <SectionHead num="03" title="运行环境" aside="Runtime" />
      <div style={{ display: 'flex', gap: 9, marginBottom: 16, flexWrap: 'wrap' }}>
        <Button onClick={() => void check()}>检测 Worker 与登录配置</Button>
        <Pill tone={vaultExists ? 'ok' : 'warn'}>{vaultExists ? 'VAULT EXISTS' : 'NO VAULT'}</Pill>
      </div>
      {error ? <Callout neutral>无法连接 Worker：{error}。本地模式仍可正常使用（会话与密钥留在本机）。</Callout> : null}
      <dl className="kv" style={{ marginBottom: 24 }}>
        <dt>部署站点</dt><dd className="mono">https://ai.solyoung.top/ · GitHub Pages（静态）</dd>
        <dt>产品形态</dt><dd>Work Agent（自带模型的本地任务型 Agent）</dd>
        <dt>当前调用方式</dt><dd className="mono">{CALL_MODE_LABELS[runtime.callMode]}</dd>
        <dt>Worker 地址</dt><dd className="mono">{runtime.apiBase || '本站同源 /api（未部署 Worker）'}</dd>
        <dt>当前身份</dt><dd>{me ? (me.isGuest ? '访客（本地模式）' : `${me.displayName ?? me.userId} · ${me.tier} · ${me.provider}`) : '访客（Worker 未连接）'}</dd>
        <dt>模型配置</dt><dd className="mono">{providers.length} 条（仅元数据存本机）</dd>
        <dt>会话 / 产物</dt><dd className="mono">{sessions.length} 个会话（本机 IndexedDB）</dd>
        <dt>Agent 协议</dt><dd className="mono">v{AGENT_PROTOCOL_VERSION} · 每步严格 JSON · 非流式 · 默认上限 {DEFAULT_MAX_STEPS} 步</dd>
        <dt>本地工具</dt><dd className="mono">{TOOL_REGISTRY.length} 个（可插拔）</dd>
        <dt>认证适配器</dt><dd className="mono">{auth?.activeAdapter ?? 'opaque-session（未检测）'} · 前端登录入口已预留、未启用</dd>
        <dt>Worker 健康</dt><dd className="mono">{health ? `${health.service} v${health.version} · ${health.time}` : '未检测'}</dd>
      </dl>
      {auth ? (
        <div style={{ marginBottom: 32 }}>
          {auth.providers.map((p) => (
            <div className="row" key={p.id}>
              <div className="row-main"><div className="row-name">{p.id.toUpperCase()} OAuth <Pill tone={p.configured ? 'ok' : 'warn'}>{p.configured ? '已配置' : '未配置'}</Pill></div><div className="row-meta">{p.note}</div></div>
            </div>
          ))}
          <div className="notice" style={{ marginTop: 8 }}>{auth.note}</div>
        </div>
      ) : null}

      <SectionHead num="04" title="等级与配额（预留）" aside="No payment in v1" />
      <Callout>
        <strong>暂不开发支付与订阅。</strong> 下表是 D1 中已建立的 plans 种子数据，用于未来的功能权限、会话数、存储、团队人数、并发与自动化限制。
        会员费与用户自己的模型 API 费用严格分开：BYOK 用户的模型账单永远不算作 SOL AI 收入。
      </Callout>
      <div className="stat-grid" style={{ gridTemplateColumns: 'repeat(4, 1fr)', marginBottom: 32 }}>
        {TIERS.map((t) => (
          <div className="stat" key={t.id}>
            <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 14 }}>{t.name}</div>
            <div className="stat-lbl" style={{ marginTop: 8, lineHeight: 1.9 }}>
              项目 {t.projects} · 存储 {t.storage}<br />团队 {t.team} 人 · 并发 {t.concurrency}
            </div>
          </div>
        ))}
      </div>

      <SectionHead num="05" title="尚未实现" aside="Honest status" />
      <div className="stage-list">
        {[
          'GitHub / Google / Email OAuth 回调与会话签发（入口已保留，需客户端凭据）',
          'Cloudflare Worker 云端部署、D1 / R2 绑定与多用户云端同步（需账号授权）',
          '流式输出（SSE）：当前代理返回完整响应体，第一版为非流式逐步执行',
          '浏览器外部工具：联网搜索、代码执行、第三方 API（第一版只提供真实本地工具）',
          '多 Agent 协作、任务编排与后台定时运行',
          '会话级预算硬限制与使用记录云端汇总（费用未知时只标注未知，不虚构金额）',
          'B.AI Opus / 视频 API 真实接入（需官方开发者文档核实地址、协议与 Model ID）',
        ].map((s, i) => (
          <div className="stage" key={s}><span className="stage-n">{String(i + 1).padStart(2, '0')}</span><div className="stage-b"><div className="stage-t">{s}</div></div><Pill tone="warn">未实现</Pill></div>
        ))}
      </div>

      <div className="notice">
        完整清单见仓库 docs/ROADMAP.md，Agent 架构与扩展方式见 docs/AGENT.md。
      </div>
    </>
  );
}
