/**
 * Work Agent execution engine.
 *
 * Every step is either a REAL upstream model call or a REAL local tool run.
 * There is no simulated thinking, no canned reply, no "demo mode".
 *
 * Guarantees:
 * - No model configured / vault locked / no secret -> preflight refuses to start.
 * - An upstream error is classified and terminates the run. It is never
 *   retried through a second transport (that could double-charge).
 * - A non-conforming model response is rejected with an explicit reason.
 * - Stopping takes effect BETWEEN steps; an in-flight HTTP call is not aborted
 *   (the current proxy has no AbortSignal). The UI says so honestly.
 * - All persisted strings are redacted before IndexedDB.
 */

import { classifyResponse } from './adapter';
import { buildAgentCall, buildSystemPrompt, parseAgentAction, supportsAgentLoop, extractModelText, type AgentTurn } from './agentProtocol';
import { sanitize, saveSession } from './agentStore';
import type { AgentMessage, AgentSession, AgentStep } from './agentTypes';
import { newId } from './crypto';
import { buildPreflight, formatEstimate, type Preflight } from './cost';
import { proxyRequest } from './apiClient';
import type { CallMode } from './runtime';
import { runTool, type ToolContext } from './tools';
import type { ProviderConfig, ProxyEnvelope, ProxyResponse } from './types';

const MAX_EVENT_CHARS = 2000;
const MAX_HISTORY_TURNS = 24;

export interface AgentPreflightInput {
  provider: ProviderConfig | undefined;
  vaultUnlocked: boolean;
  hasSecret: boolean;
  callMode: CallMode;
  apiOnline: boolean;
  maxSteps: number;
}

export interface AgentPreflightResult {
  ok: boolean;
  blocking: string[];
  notices: string[];
  cost: Preflight | null;
  lines: string[];
}

/**
 * Everything the user must see BEFORE a billable run: provider, model,
 * expected volume, estimated cost (UNKNOWN when no price basis), budget,
 * and transport. Pure — performs no network request.
 */
export function preflightAgent(input: AgentPreflightInput): AgentPreflightResult {
  const { provider, maxSteps } = input;
  const blocking: string[] = [];
  const notices: string[] = [];

  if (!provider) blocking.push('尚未选择模型。请先在「模型」里配置并选中一个文本 Provider。');
  else {
    if (!provider.enabled) blocking.push(`Provider「${provider.name}」已停用。`);
    if (!provider.capabilities.includes('text')) blocking.push('该 Provider 未标注 text 能力。能力必须显式声明，系统不会从模型名称推断。');
    if (!provider.modelId) blocking.push('该 Provider 尚未填写 Model ID。');
    if (!provider.baseUrl) blocking.push('该 Provider 尚未填写 API Base URL。');
    if (!supportsAgentLoop(provider)) blocking.push(`协议 ${provider.protocol} 不支持 Agent 对话循环。`);
    if (!provider.lastTest || provider.lastTest.code !== 'CONNECTION_OK') {
      notices.push('该 Provider 尚未通过真实连接测试；仍可尝试运行，但失败风险由你自行承担。');
    }
  }
  if (!input.vaultUnlocked) blocking.push('密钥保险库已锁定，请先解锁。');
  else if (!input.hasSecret) blocking.push('保险库中没有该 Provider 的 API Key，请先保存 Key。');
  if (input.callMode === 'worker' && !input.apiOnline) {
    blocking.push('当前为「仅 Worker 代理」模式，但 Worker 不在线。请在设置里填写可用地址或切换为自动模式。');
  }
  if (input.callMode !== 'worker' && !input.apiOnline) {
    notices.push('当前 Worker 不可达，模型调用将走浏览器直连；上游未开放 CORS 时会明确报「直连失败」，不会被伪装成成功。');
  }
  notices.push('第一版为非流式：每步等待模型完整返回后展示。中止在步骤之间生效，正在进行的请求不会被打断。');

  const cost = provider
    ? buildPreflight(
        provider,
        { requests: maxSteps, inputTokens: 1200 * maxSteps, outputTokens: 800 * maxSteps },
        null,
        0,
      )
    : null;

  const lines = [
    `Provider：${provider?.name ?? '未选择'}`,
    `模型：${provider?.modelId || '(未填写)'} · 协议 ${provider?.protocol ?? '-'}`,
    `预计调用量：最多 ${maxSteps} 次真实模型请求 + 若干本地工具（不额外收费）`,
    `预计费用：${cost ? formatEstimate(cost.estimate) : '未知（未选择模型）'}${cost?.estimate.status === 'known' ? `（单次估算，实际以服务商账单为准）` : ''}`,
    '当前预算：未设置（第一版不在会话层强制限额）',
    `调用通道：${input.callMode === 'worker' ? 'Worker 代理' : input.callMode === 'direct' ? '浏览器直连' : '自动（优先 Worker）'}`,
  ];

  if (cost?.estimate.status === 'unknown') notices.push(cost.estimate.reason);

  return { ok: blocking.length === 0, blocking, notices, cost, lines };
}

export interface RunAgentInput {
  session: AgentSession;
  provider: ProviderConfig;
  apiKey: string;
  providerCount: number;
  onUpdate?: (session: AgentSession) => void | Promise<void>;
  shouldStop?: () => boolean;
  /** Injectable for unit tests. Production always uses the real proxy. */
  proxy?: (envelope: ProxyEnvelope) => Promise<ProxyResponse>;
  toolRunner?: typeof runTool;
  persist?: (session: AgentSession) => Promise<void>;
}

function message(role: AgentMessage['role'], content: string, extra: Partial<AgentMessage> = {}): AgentMessage {
  return { id: newId('msg_'), role, content: sanitize(content), createdAt: new Date().toISOString(), ...extra };
}

function step(index: number, kind: AgentStep['kind'], summary: string, extra: Partial<AgentStep> = {}): AgentStep {
  return {
    index,
    kind,
    at: new Date().toISOString(),
    summary: sanitize(summary).slice(0, 300),
    ok: kind !== 'error',
    ...extra,
  };
}

function toTurns(messages: readonly AgentMessage[]): AgentTurn[] {
  const usable = messages.filter((m) => m.role === 'user' || m.role === 'assistant' || m.role === 'tool');
  const recent = usable.slice(-MAX_HISTORY_TURNS);
  return recent.map((m) => ({
    role: m.role as 'user' | 'assistant' | 'tool',
    content: m.content,
    ...(m.toolId ? { toolId: m.toolId } : {}),
  }));
}

export async function runAgent(input: RunAgentInput): Promise<AgentSession> {
  const callProxy = input.proxy ?? proxyRequest;
  const executeTool = input.toolRunner ?? runTool;
  const persist = input.persist ?? saveSession;

  let current: AgentSession = { ...input.session, state: 'running', lastError: undefined };
  if (current.messages.length === 0) {
    current = { ...current, messages: [message('user', current.goal)] };
  }

  const emit = async (): Promise<void> => {
    await persist(current);
    await input.onUpdate?.(current);
  };
  await emit();

  const fail = async (reason: string): Promise<AgentSession> => {
    current = {
      ...current,
      state: 'failed',
      lastError: sanitize(reason).slice(0, 2000),
      steps: [...current.steps, step(current.steps.length + 1, 'error', reason, { ok: false })],
      messages: [...current.messages, message('event', `执行失败：${reason}`)],
    };
    await emit();
    return current;
  };

  for (let iteration = 1; iteration <= current.maxSteps; iteration += 1) {
    if (input.shouldStop?.()) {
      current = {
        ...current,
        state: 'cancelled',
        lastError: '用户中止。已在步骤之间停止，未产生结论。',
        steps: [...current.steps, step(current.steps.length + 1, 'cancel', '用户中止', { ok: false })],
      };
      await emit();
      return current;
    }

    const systemPrompt = buildSystemPrompt(current, iteration);
    const built = buildAgentCall({
      provider: input.provider,
      apiKey: input.apiKey,
      systemPrompt,
      turns: toTurns(current.messages),
    });
    if (!built.ok) return fail(built.error);

    let response: ProxyResponse;
    try {
      response = await callProxy(built.envelope);
    } catch (e) {
      return fail(`调用通道异常：${e instanceof Error ? e.message : String(e)}`);
    }

    const classified = classifyResponse(response.status, response.body, response.transportError);
    const callMeta: AgentMessage['call'] = {
      providerId: input.provider.id,
      modelId: input.provider.modelId,
      protocol: input.provider.protocol,
      httpStatus: classified.httpStatus,
      latencyMs: response.elapsedMs,
      transport: response.transport,
      ...(response.ok ? {} : { errorCode: classified.code }),
    };

    current = {
      ...current,
      steps: [
        ...current.steps,
        step(current.steps.length + 1, 'model', `第 ${iteration} 步 · ${input.provider.name} / ${input.provider.modelId} · ${classified.label}`, {
          ok: response.ok && !response.transportError,
          latencyMs: response.elapsedMs,
          httpStatus: classified.httpStatus,
          transport: response.transport,
          detail: `HTTP ${response.status} · ${classified.detail}`,
        }),
      ],
      messages: [
        ...current.messages,
        message('assistant', `收到模型响应 · ${classified.label} · ${response.elapsedMs}ms`, { call: callMeta }),
        message('event', `原始模型响应（已脱敏）：\n${sanitize(response.body).slice(0, MAX_EVENT_CHARS)}`),
      ],
    };
    await emit();

    if (response.transportError || !response.ok) {
      return fail(`${classified.label}：${classified.detail}`);
    }

    const text = sanitize(extractModelText(response.body));
    const parsed = parseAgentAction(text);
    if (!parsed.ok) {
      return fail(`${parsed.error} 已保留原始响应供检查，未把自然语言当作执行结果。`);
    }

    if (parsed.action.final !== undefined) {
      current = {
        ...current,
        state: 'succeeded',
        steps: [...current.steps, step(current.steps.length + 1, 'final', '任务完成，模型给出最终答复', { ok: true })],
        messages: [
          ...current.messages,
          message('assistant', `进展：${parsed.action.thought}`),
          message('assistant', parsed.action.final, { call: callMeta }),
        ],
      };
      await emit();
      return current;
    }

    const tool = parsed.action.tool!;
    const ctx: ToolContext = { session: current, providerCount: input.providerCount };
    let result;
    try {
      result = await executeTool(tool.id, ctx, tool.args);
    } catch (e) {
      result = { ok: false, output: `工具执行异常：${e instanceof Error ? e.message : String(e)}` };
    }
    const output = sanitize(result.output);
    current = {
      ...current,
      steps: [
        ...current.steps,
        step(current.steps.length + 1, 'tool', `${tool.id} · ${result.ok ? '执行成功' : '执行失败'}`, {
          ok: result.ok,
          toolId: tool.id,
          detail: output.slice(0, 2000),
        }),
      ],
      messages: [
        ...current.messages,
        message('assistant', `进展：${parsed.action.thought}`),
        message('tool', output, { toolId: tool.id }),
      ],
    };
    await emit();
  }

  return fail(`已达到最大步数 ${current.maxSteps}，模型未给出 final。本次运行没有产生结论，也没有伪造结果。`);
}
