import { useApp } from '../state/AppContext';
import { Button, Empty, SectionHead } from '../components/ui';
import { listArtifacts } from '../lib/agentStore';
import type { AgentRunState } from '../lib/agentTypes';

const STATE_LABEL: Record<AgentRunState, string> = {
  idle: '待运行',
  running: '运行中',
  succeeded: '已完成',
  failed: '失败',
  cancelled: '已中止',
};

export function Sessions(): JSX.Element {
  const { sessions, openSession, removeSession, navigate, providers, activeSessionId } = useApp();

  const exportAll = async () => {
    const bundles = await Promise.all(
      sessions.map(async (s) => ({ session: s, artifacts: await listArtifacts(s.id) })),
    );
    const url = URL.createObjectURL(new Blob([JSON.stringify({ product: 'SOL AI', exported_at: new Date().toISOString(), bundles }, null, 2)], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'sol-ai-sessions.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <>
      <div className="page-head">
        <h1 className="page-title display">会话</h1>
        <p className="page-lede">每次任务都是一个独立会话，包含真实模型调用、工具执行、消息与交付物。全部保存在本机浏览器，不上传。</p>
      </div>

      <SectionHead num="01" title="全部会话" aside={`${sessions.length} 个`} />

      <div style={{ display: 'flex', gap: 9, marginBottom: 22, flexWrap: 'wrap' }}>
        <Button onClick={() => navigate('home')}>新建任务</Button>
        <Button onClick={() => void exportAll()} disabled={sessions.length === 0}>导出全部会话</Button>
      </div>

      {sessions.length === 0 ? (
        <Empty
          title="还没有会话"
          desc="回到工作台写下一个任务，确认调用信息后就会创建会话。SOL AI 不会预置示例会话或伪造运行结果。"
          action={<Button variant="primary" onClick={() => navigate('home')}>去工作台</Button>}
        />
      ) : sessions.map((s) => {
        const provider = providers.find((p) => p.id === s.providerId);
        return (
          <div className="row" key={s.id}>
            <div className="row-main">
              <div className="row-name">
                {s.title}
                <span className="faint" style={{ fontSize: 11, fontWeight: 400 }}>{STATE_LABEL[s.state]}</span>
                {s.id === activeSessionId ? <span className="faint" style={{ fontSize: 11, fontWeight: 400 }}>当前</span> : null}
              </div>
              <div className="row-meta">
                {s.id} · {provider?.name ?? '(模型已删除)'} · {provider?.modelId ?? '-'} · {s.steps.length} 步 · {new Date(s.updatedAt).toLocaleString('zh-CN')}
              </div>
              <div className="row-meta" style={{ whiteSpace: 'normal', fontFamily: 'var(--font-body)' }}>{s.goal.slice(0, 140)}</div>
            </div>
            <div className="row-actions">
              <Button size="sm" variant="primary" onClick={() => openSession(s.id)}>查看</Button>
              <Button
                size="sm"
                variant="danger"
                onClick={() => { if (window.confirm(`删除会话「${s.title}」及其全部产物？此操作不可撤销。`)) void removeSession(s.id); }}
              >
                删除
              </Button>
            </div>
          </div>
        );
      })}

      <div className="notice">
        旧版本「AI Video Studio」的项目记录保留在本机 IndexedDB 中，未迁移也未删除，但不再在此展示。
      </div>
    </>
  );
}
