/**
 * Replaceable authentication boundary for SOL AI.
 *
 * The UI (pages/Account.tsx) depends ONLY on this interface. Business logic
 * never imports an OAuth SDK, a vendor user object, or a session library.
 * When login is implemented later, provide a real AuthAdapter via
 * `setAuthAdapter()` and swap the disabled buttons for `beginLogin()`.
 *
 * v1 deliberately ships the unavailable adapter. It does NOT create a fake
 * session, a fake user, or a fake "logged in" state.
 */

import type { Identity, Tier } from './types';

export type AuthStatus = 'unavailable' | 'ready';

export interface AuthEntrance {
  id: string;
  label: string;
  enabled: boolean;
  note: string;
}

export interface AuthAdapter {
  id: string;
  label: string;
  status: AuthStatus;
  /** Entrances shown in the UI. `enabled: false` means the button is inert. */
  entrances(): readonly AuthEntrance[];
  /** Resolve the current identity. Return null when there is no session. */
  resolveIdentity(): Promise<Identity | null>;
  /** Start a login flow. Must reject when the adapter is unavailable. */
  beginLogin(entranceId: string): Promise<void>;
}

export const GUEST_IDENTITY: Identity = {
  userId: 'local-guest',
  workspaceId: 'local',
  tier: 'free' as Tier,
  provider: 'local',
  isGuest: true,
};

export const unavailableAuthAdapter: AuthAdapter = {
  id: 'unavailable',
  label: '访客本地模式（登录未启用）',
  status: 'unavailable',
  entrances: () => [
    { id: 'github', label: '使用 GitHub 登录', enabled: false, note: 'OAuth App 客户端凭据未配置' },
    { id: 'google', label: '使用 Google 登录', enabled: false, note: 'OAuth Client 未配置' },
    { id: 'email', label: '使用邮箱登录', enabled: false, note: '邮件服务与验证码通道未实现' },
  ],
  resolveIdentity: async () => GUEST_IDENTITY,
  beginLogin: async () => {
    throw new Error('登录系统尚未启用。当前为访客本地模式，未发起任何认证请求。');
  },
};

let currentAdapter: AuthAdapter = unavailableAuthAdapter;

export function getAuthAdapter(): AuthAdapter {
  return currentAdapter;
}

/** Future integration point. Not called anywhere in v1. */
export function setAuthAdapter(next: AuthAdapter): void {
  currentAdapter = next;
}

export function resetAuthAdapter(): void {
  currentAdapter = unavailableAuthAdapter;
}
