import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import type { Identity, ProviderConfig } from '../lib/types';
import type { AgentSession } from '../lib/agentTypes';
import { idbGet, idbSet, KV, STORE_KV } from '../lib/idb';
import { vault } from '../lib/vault';
import {
  createSession,
  deleteSession,
  listSessions,
  saveSession,
  type CreateSessionInput,
} from '../lib/agentStore';
import { getMe } from '../lib/apiClient';
import { getRuntimeConfig, setRuntimeConfig, RUNTIME_CHANGE_EVENT, type RuntimeConfig } from '../lib/runtime';

export type Route = 'home' | 'sessions' | 'providers' | 'vault' | 'account' | 'settings';

interface AppState {
  route: Route;
  navigate: (route: Route) => void;
  providers: ProviderConfig[];
  saveProviders: (next: ProviderConfig[]) => Promise<void>;
  reloadProviders: () => Promise<void>;
  sessions: AgentSession[];
  activeSessionId: string | null;
  openSession: (id: string) => void;
  newSession: (input: CreateSessionInput) => Promise<AgentSession>;
  updateSession: (session: AgentSession) => Promise<void>;
  removeSession: (id: string) => Promise<void>;
  reloadSessions: () => Promise<void>;
  /** Explicit user choice. Empty means no model selected — never auto-inferred. */
  selectedProviderId: string;
  setSelectedProviderId: (id: string) => void;
  vaultReady: boolean;
  vaultExists: boolean;
  vaultUnlocked: boolean;
  refreshVault: () => Promise<void>;
  me: Identity | null;
  apiOnline: boolean;
  storageError: string | null;
  runtime: RuntimeConfig;
  setRuntime: (next: RuntimeConfig) => void;
  theme: 'light' | 'dark';
  setTheme: (t: 'light' | 'dark') => void;
}

const Ctx = createContext<AppState | null>(null);

export function AppProvider({ children }: { children: ReactNode }): JSX.Element {
  const [route, setRoute] = useState<Route>('home');
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [providers, setProviders] = useState<ProviderConfig[]>([]);
  const [sessions, setSessions] = useState<AgentSession[]>([]);
  const [selectedProviderId, setSelectedId] = useState('');
  const [vaultReady, setVaultReady] = useState(false);
  const [vaultExists, setVaultExists] = useState(false);
  const [vaultUnlocked, setVaultUnlocked] = useState(false);
  const [me, setMe] = useState<Identity | null>(null);
  const [apiOnline, setApiOnline] = useState(false);
  const [storageError, setStorageError] = useState<string | null>(null);
  const [theme, setThemeState] = useState<'light' | 'dark'>('light');
  const [runtime, setRuntimeState] = useState<RuntimeConfig>(() => getRuntimeConfig());

  const setRuntime = useCallback((next: RuntimeConfig) => {
    setRuntimeConfig(next);
    setRuntimeState(getRuntimeConfig());
  }, []);

  useEffect(() => {
    const sync = () => setRuntimeState(getRuntimeConfig());
    window.addEventListener(RUNTIME_CHANGE_EVENT, sync);
    return () => window.removeEventListener(RUNTIME_CHANGE_EVENT, sync);
  }, []);

  // IndexedDB can be unavailable (private mode, blocked storage, embedded
  // webviews). The app must still render and say so honestly, never hang on
  // an endless loading screen.
  const refreshVault = useCallback(async () => {
    try {
      await Promise.race([
        vault.initialize(),
        new Promise<never>((_, reject) =>
          window.setTimeout(() => reject(new Error('本地存储初始化超时')), 3_000),
        ),
      ]);
    } catch (e) {
      setStorageError(e instanceof Error ? e.message : '本地存储不可用');
    }
    setVaultExists(vault.exists);
    setVaultUnlocked(vault.unlocked);
    setVaultReady(true);
  }, []);

  const reloadProviders = useCallback(async () => {
    setProviders((await idbGet<ProviderConfig[]>(STORE_KV, KV.providers)) ?? []);
  }, []);

  const saveProviders = useCallback(async (next: ProviderConfig[]) => {
    await idbSet(STORE_KV, KV.providers, next);
    setProviders(next);
  }, []);

  const reloadSessions = useCallback(async () => {
    setSessions(await listSessions());
  }, []);

  const newSession = useCallback(async (input: CreateSessionInput) => {
    const created = await createSession(input);
    await reloadSessions();
    return created;
  }, [reloadSessions]);

  /** Called by the engine after every REAL step. Writes once (engine persist is disabled). */
  const updateSession = useCallback(async (session: AgentSession) => {
    await saveSession(session);
    setSessions((prev) => {
      const index = prev.findIndex((s) => s.id === session.id);
      if (index === -1) return [session, ...prev];
      const next = [...prev];
      next[index] = session;
      return next;
    });
  }, []);

  const removeSession = useCallback(async (id: string) => {
    await deleteSession(id);
    setActiveSessionId((current) => (current === id ? null : current));
    await reloadSessions();
  }, [reloadSessions]);

  const setSelectedProviderId = useCallback((id: string) => {
    setSelectedId(id);
    void idbSet(STORE_KV, KV.selectedProvider, id).catch(() => {});
  }, []);

  const setTheme = useCallback((t: 'light' | 'dark') => {
    setThemeState(t);
    document.documentElement.setAttribute('data-theme', t);
    void idbSet(STORE_KV, KV.settings, { theme: t });
  }, []);

  useEffect(() => {
    void (async () => {
      try { await refreshVault(); } catch { setVaultReady(true); }
      for (const task of [reloadProviders, reloadSessions]) {
        try { await task(); } catch (e) { setStorageError(e instanceof Error ? e.message : '本机数据读取失败'); }
      }
      try {
        const settings = await idbGet<{ theme?: 'light' | 'dark' }>(STORE_KV, KV.settings);
        if (settings?.theme) setTheme(settings.theme);
      } catch { /* ignore */ }
      try {
        const saved = await idbGet<string>(STORE_KV, KV.selectedProvider);
        if (saved) setSelectedId(saved);
      } catch { /* ignore */ }
      try {
        const identity = await getMe();
        setMe(identity);
        setApiOnline(true);
      } catch {
        // Static site / Worker offline: honest local-only mode, no fake cloud state.
        setMe(null);
        setApiOnline(false);
      }
    })();
  }, [refreshVault, reloadProviders, reloadSessions, setTheme]);

  const value = useMemo<AppState>(
    () => ({
      route,
      navigate: setRoute,
      providers,
      saveProviders,
      reloadProviders,
      sessions,
      activeSessionId,
      openSession: (id) => { setActiveSessionId(id); setRoute('home'); },
      newSession,
      updateSession,
      removeSession,
      reloadSessions,
      selectedProviderId,
      setSelectedProviderId,
      vaultReady,
      vaultExists,
      vaultUnlocked,
      refreshVault,
      me,
      apiOnline,
      storageError,
      runtime,
      setRuntime,
      theme,
      setTheme,
    }),
    [route, providers, saveProviders, reloadProviders, sessions, activeSessionId, newSession, updateSession, removeSession, reloadSessions, selectedProviderId, setSelectedProviderId, vaultReady, vaultExists, vaultUnlocked, refreshVault, me, apiOnline, storageError, runtime, setRuntime, theme, setTheme],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useApp(): AppState {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
}
