/**
 * Work Agent wire protocol — pure functions, no network, no persistence.
 *
 * The agent does NOT depend on any vendor's `tool_calling` format. Instead the
 * model is asked for one strict JSON action per turn. This keeps the same loop
 * working across OpenAI-compatible, Anthropic and custom HTTP providers.
 *
 * HARD RULE: a non-conforming response is REJECTED with an explicit reason.
 * It is never "repaired" into a success and never turned into a fake reply.
 */

import { buildRequest } from './adapter';
import { AGENT_PROTOCOL_VERSION, type AgentAction, type AgentSession } from './agentTypes';
import { TOOL_IDS, toolCatalogForPrompt } from './tools';
import type { ProviderConfig, ProxyEnvelope } from './types';

export const AGENT_SUPPORTED_PROTOCOLS = ['openai-compatible', 'anthropic', 'custom-http'] as const;

export function supportsAgentLoop(provider: ProviderConfig): boolean {
  return (AGENT_SUPPORTED_PROTOCOLS as readonly string[]).includes(provider.protocol);
}

export function buildSystemPrompt(session: AgentSession, step: number): string {
  return [
    `你是 SOL AI 的工作 Agent（协议 v${AGENT_PROTOCOL_VERSION}）。你在用户自己的工作台里执行真实任务，用户自带 API 模型。`,
    '',
    '【输出格式 — 必须严格遵守】',
    '每一轮只输出一个 JSON 对象，不要输出 Markdown 代码块、解释文字或任何 JSON 之外的内容。',
    '结构只有两种，二选一：',
    '  需要调用工具：{"thought":"当前进展的真实判断","tool":{"id":"工具ID","args":{...}},"final":null}',
    '  任务已完成：  {"thought":"当前进展的真实判断","tool":null,"final":"给用户的最终答复"}',
    'tool 与 final 必须恰好一个非 null；thought 必须是字符串；final 必须是非空字符串。',
    '',
    '【行为规则】',
    '1. 不要编造工具执行结果。工具结果会由系统以「[工具 … 的真实执行结果]」开头的用户消息回传给你。',
    '2. 需要交付文件时必须使用 artifact.write；需要确认已有内容时用 artifact.list / artifact.read。',
    '3. 只有工具真实返回成功后，才能在 final 里说该文件已保存。不要声称完成了没有实际做的事。',
    '4. 遇到无法完成、信息不足或模型能力不够时，用 final 明确说明原因，不要假装成功。',
    '5. 不要修改或删减用户的原始任务描述；它是只读输入。',
    '6. 尽量少用步骤，能直接回答就直接给 final。',
    '',
    `【执行进度】第 ${step} 步，最多 ${session.maxSteps} 步。超过上限任务会被判为失败，因此请在上限内给出 final。`,
    '',
    '【可用工具】',
    toolCatalogForPrompt(),
    '',
    '可用工具 ID：' + TOOL_IDS.join(', '),
  ].join('\n');
}

/** Strip a single markdown code fence, then parse the outermost JSON object. No repair. */
export function extractJsonObject(text: string): unknown | null {
  let candidate = text.trim();
  const fenced = candidate.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) candidate = (fenced[1] ?? '').trim();
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1)) as unknown;
  } catch {
    return null;
  }
}

export type ActionParse =
  | { ok: true; action: AgentAction }
  | { ok: false; error: string };

export function parseAgentAction(text: string): ActionParse {
  const parsed = extractJsonObject(text);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { ok: false, error: '模型没有返回可解析的 JSON 对象。SOL AI 不会把自然语言回复当作已完成的动作。' };
  }
  const obj = parsed as Record<string, unknown>;
  if (typeof obj.thought !== 'string') {
    return { ok: false, error: '协议校验失败：thought 必须是字符串。' };
  }
  const hasTool = obj.tool !== null && obj.tool !== undefined;
  const hasFinal = obj.final !== null && obj.final !== undefined;
  if (hasTool === hasFinal) {
    return { ok: false, error: '协议校验失败：tool 与 final 必须恰好一个非 null。' };
  }

  if (hasFinal) {
    if (typeof obj.final !== 'string' || !obj.final.trim()) {
      return { ok: false, error: '协议校验失败：final 必须是非空字符串。' };
    }
    return { ok: true, action: { thought: obj.thought, final: obj.final } };
  }

  const tool = obj.tool;
  if (!tool || typeof tool !== 'object' || Array.isArray(tool)) {
    return { ok: false, error: '协议校验失败：tool 必须是对象。' };
  }
  const t = tool as Record<string, unknown>;
  if (typeof t.id !== 'string' || !TOOL_IDS.includes(t.id)) {
    return { ok: false, error: `协议校验失败：未知工具 ${String(t.id)}。可用：${TOOL_IDS.join(', ')}` };
  }
  if (t.args !== undefined && t.args !== null && (typeof t.args !== 'object' || Array.isArray(t.args))) {
    return { ok: false, error: '协议校验失败：tool.args 必须是对象。' };
  }
  return {
    ok: true,
    action: { thought: obj.thought, tool: { id: t.id, args: (t.args ?? {}) as Record<string, unknown> } },
  };
}

/** Extract assistant text from the most common real response shapes. */
export function extractModelText(body: string): string {
  try {
    const j = JSON.parse(body) as Record<string, unknown>;
    const choices = j.choices as Array<{ message?: { content?: unknown }; text?: unknown }> | undefined;
    const content = choices?.[0]?.message?.content;
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
      const parts = (content as Array<{ text?: unknown }>).map((p) => (typeof p?.text === 'string' ? p.text : '')).filter(Boolean);
      if (parts.length) return parts.join('\n');
    }
    if (typeof choices?.[0]?.text === 'string') return choices[0].text;
    const blocks = j.content as Array<{ text?: unknown }> | undefined;
    if (Array.isArray(blocks)) {
      const parts = blocks.map((b) => (typeof b?.text === 'string' ? b.text : '')).filter(Boolean);
      if (parts.length) return parts.join('\n');
    }
    for (const key of ['output_text', 'text', 'response', 'result']) {
      if (typeof j[key] === 'string') return j[key] as string;
    }
  } catch {
    /* plain text response */
  }
  return body;
}

export interface AgentTurn {
  role: 'user' | 'assistant' | 'tool';
  content: string;
  toolId?: string;
}

/** Merge consecutive same-role turns (required by Anthropic, harmless elsewhere). */
export function normalizeTurns(turns: readonly AgentTurn[]): Array<{ role: 'user' | 'assistant'; content: string }> {
  const out: Array<{ role: 'user' | 'assistant'; content: string }> = [];
  for (const turn of turns) {
    const role: 'user' | 'assistant' = turn.role === 'assistant' ? 'assistant' : 'user';
    const content =
      turn.role === 'tool'
        ? `[工具 ${turn.toolId ?? 'unknown'} 的真实执行结果]\n${turn.content}`
        : turn.content;
    const last = out[out.length - 1];
    if (last?.role === role) last.content = `${last.content}\n\n${content}`;
    else out.push({ role, content });
  }
  return out;
}

export type AgentCallBuild =
  | { ok: true; envelope: ProxyEnvelope }
  | { ok: false; error: string };

/** Build ONE real upstream chat request. No streaming (the proxy returns full bodies). */
export function buildAgentCall(args: {
  provider: ProviderConfig;
  apiKey: string;
  systemPrompt: string;
  turns: readonly AgentTurn[];
}): AgentCallBuild {
  const { provider, apiKey, systemPrompt } = args;
  if (!supportsAgentLoop(provider)) {
    return { ok: false, error: `Provider 协议 ${provider.protocol} 不是文本对话协议，无法运行 Agent 循环。请配置 OpenAI 兼容 / Anthropic / 自定义 HTTP 的文本模型。` };
  }
  if (!provider.modelId) return { ok: false, error: '该 Provider 尚未填写 Model ID。' };
  if (!provider.baseUrl) return { ok: false, error: '该 Provider 尚未填写 API Base URL。' };

  const turns = normalizeTurns(args.turns);
  const isAnthropic = provider.protocol === 'anthropic';
  const path = provider.endpoints.chat ?? (isAnthropic ? '/messages' : '/chat/completions');

  const body = isAnthropic
    ? {
        model: provider.modelId,
        max_tokens: 4096,
        system: systemPrompt,
        messages: turns,
        ...provider.requestParams,
      }
    : {
        model: provider.modelId,
        messages: [{ role: 'system', content: systemPrompt }, ...turns],
        temperature: 0.2,
        stream: false,
        ...provider.requestParams,
      };

  return {
    ok: true,
    envelope: buildRequest(provider, apiKey, { path, body }),
  };
}
