import { useEffect, useMemo, useRef, useState } from 'react';
import { useApp } from '../state/AppContext';
import { preflightAgent, runAgent } from '../lib/agentEngine';
import { listArtifacts } from '../lib/agentStore';
import {
  DEFAULT_MAX_STEPS,
  extensionForFormat,
  mimeForFormat,
  type AgentArtifact,
  type AgentRunState,
} from '../lib/agentTypes';
import { supportsAgentLoop } from '../lib/agentProtocol';
import { protocolLabel } from '../lib/providers';
import { TOOL_REGISTRY } from '../lib/tools';
import { vault } from '../lib/vault';
import { Button } from '../components/ui';

const STATE_LABEL: Record<AgentRunState, string> = {
  idle: '待运行',
  running: '运行中',
  succeeded: '已完成',
  failed: '失败',
  cancelled: '已中止',
};

const STEP_LABEL: Record<string, string> = {
  model: '模型调用',
  tool: '工具执行',
  final: '完成',
  error: '错误',
  cancel: '中止',
};

const ROLE_LABEL: Record<string, string> = {
  user: '任务',
  assistant: 'Agent',
  tool: '工具结果',
  event: '事件',
  system: '系统',
};

function download(filename: string, content: string, mime: string): void {
  const url = URL.createObjectURL(new Blob([content], { type: mime }));
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export function Home(): JSX.Element {
  const {
    navigate, providers, selectedProviderId, setSelectedProviderId,
    vaultExists, vaultUnlocked, apiOnline, runtime,
    sessions, activeSessionId, openSession, newSession, updateSession,
  } = useApp();

  const [draft, setDraft] = useState('');
  const [showPreflight, setShowPreflight] = useState(false);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState('');
  const [artifacts, setArtifacts] = useState<AgentArtifact[]>([]);
  const stopRef = useRef(false);

  const textProviders = providers.filter(
    (p) => p.enabled && p.capabilities.includes('text') && supportsAgentLoop(p),
  );
  const selected = textProviders.find((p) => p.id === selectedProviderId);
  const activeSession = sessions.find((s) => s.id === activeSessionId) ?? null;

  const preflight = useMemo(
    () => preflightAgent({
      provider: selected,
      vaultUnlocked,
      hasSecret: selected ? vault.hasSecret(selected.id) : false,
      callMode: runtime.callMode,
      apiOnline,
      maxSteps: DEFAULT_MAX_STEPS,
    }),
    [selected, vaultUnlocked, runtime.callMode, apiOnline],
  );

  useEffect(() => {
    if (!activeSessionId) { setArtifacts([]); return; }
    let alive = true;
    void listArtifacts(activeSessionId).then((list) => { if (alive) setArtifacts(list); });
    return () => { alive = false; };
  }, [activeSessionId, activeSession?.steps.length]);

  const prepare = () => {
    if (!draft.trim()) return setError('请先写下要交给 Agent 完成的任务。');
    if (!selected) return setError('请先在下方选择一个已配置、已启用且标注了 text 能力的模型。');
    setError('');
    setShowPreflight(true);
  };

  const confirm = async () => {
    if (!selected || !draft.trim() || running) return;
    const secret = vault.getSecret(selected.id);
    if (!secret) return setError('无法读取该模型的 API Key，请先解锁密钥保险库。');

    stopRef.current = false;
    setRunning(true);
    setShowPreflight(false);
    setError('');
    try {
      const fresh = await newSession({ goal: draft.trim(), providerId: selected.id, maxSteps: DEFAULT_MAX_STEPS });
      openSession(fresh.id);
      const result = await runAgent({
        session: fresh,
        provider: selected,
        apiKey: secret.apiKey,
        providerCount: providers.filter((p) => p.enabled).length,
        // The engine's onUpdate persists once per step; avoid a double write.
        persist: async () => {},
        onUpdate: async (s) => { await updateSession(s); },
        shouldStop: () => stopRef.current,
      });
      if (result.state !== 'succeeded') setError(result.lastError ?? '运行未成功完成。');
      else setDraft('');
    } catch (e) {
      setError(e instanceof Error ? e.message : '运行失败');
    } finally {
      setRunning(false);
      stopRef.current = false;
    }
  };

  const events = activeSession?.messages.filter((m) => m.role === 'event') ?? [];
  const visibleMessages = activeSession?.messages.filter((m) => m.role !== 'event') ?? [];

  return (
    <div className="home">
      <section className="home-hero">
        <div className="home-kicker">SolYoung AI Studio · Work Agent</div>
        <h1 className="home-title display">SOL AI</h1>
        <p className="home-sub">一个工作空间，连接你自己的 AI 模型，让它替你完成工作。</p>
        <p className="home-sub-en">One workspace. Your models. Your work.</p>
      </section>

      <div className="composer">
        <textarea
          className="composer-input"
          rows={4}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) prepare(); }}
          placeholder="描述你要交给 Agent 完成的任务…"
          aria-label="任务描述"
        />
        <div className="composer-bar">
          <div className="composer-meta">
            <select
              className="composer-select"
              value={selectedProviderId}
              onChange={(e) => setSelectedProviderId(e.target.value)}
              aria-label="选择模型"
            >
              <option value="">选择模型…</option>
              {textProviders.map((p) => (
                <option key={p.id} value={p.id}>{p.name}{p.modelId ? ` · ${p.modelId}` : ' · 未填 Model ID'}</option>
              ))}
            </select>
            <span>保险库{vaultUnlocked ? '已解锁' : vaultExists ? '已锁定' : '未创建'}</span>
          </div>
          <div className="composer-actions">
            <button className="text-btn" onClick={() => navigate('providers')}>配置模型</button>
            <button className="composer-send" onClick={prepare} disabled={running} aria-label="检查并准备运行" title="检查并准备运行（⌘/Ctrl + Enter）">
              <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
                <path d="M10 15.5V5M10 5 5.8 9.2M10 5l4.2 4.2" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          </div>
        </div>
      </div>
      {error ? <div className="home-error">{error}</div> : null}

      {showPreflight ? (
        <section className="home-block agent-preflight">
          <div className="home-block-head">
            <h2 className="home-block-title">调用前确认</h2>
            <button className="home-link" onClick={() => setShowPreflight(false)}>取消</button>
          </div>
          <div className="preflight-lines">
            {preflight.lines.map((line) => <div key={line}>{line}</div>)}
          </div>
          {preflight.blocking.length > 0 ? (
            <div className="home-error" style={{ textAlign: 'left', marginTop: 14 }}>
              <strong>无法开始：</strong>
              {preflight.blocking.map((b) => <div key={b}>· {b}</div>)}
            </div>
          ) : null}
          {preflight.notices.map((n) => <p className="home-empty" key={n} style={{ padding: '8px 0' }}>· {n}</p>)}
          <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginTop: 18, flexWrap: 'wrap' }}>
            <Button variant="primary" onClick={() => void confirm()} disabled={!preflight.ok || running}>确认运行</Button>
            <span className="faint" style={{ fontSize: 11 }}>只有这一步才会产生真实模型调用与费用</span>
          </div>
        </section>
      ) : null}

      {activeSession ? (
        <section className="home-block">
          <div className="home-block-head">
            <h2 className="home-block-title">运行轨迹 · {activeSession.title}</h2>
            <span className="home-block-more">{STATE_LABEL[activeSession.state]} · {activeSession.steps.length} 步</span>
          </div>
          {running ? (
            <div style={{ margin: '12px 0' }}>
              <Button size="sm" onClick={() => { stopRef.current = true; }}>停止（下一步生效）</Button>
            </div>
          ) : null}
          {activeSession.lastError ? <p className="home-error" style={{ textAlign: 'left' }}>{activeSession.lastError}</p> : null}

          {activeSession.steps.length === 0 ? (
            <p className="home-empty">尚未执行任何步骤。</p>
          ) : (
            <div className="trace">
              {activeSession.steps.map((s) => (
                <div className="trace-step" key={`${s.index}-${s.at}`}>
                  <span className="trace-n">{String(s.index).padStart(2, '0')}</span>
                  <span className="trace-kind">{STEP_LABEL[s.kind] ?? s.kind}</span>
                  <span className="trace-summary">{s.summary}</span>
                  <span className="trace-time">{s.latencyMs ? `${s.latencyMs}ms` : ''}</span>
                </div>
              ))}
            </div>
          )}

          <div className="messages">
            {visibleMessages.map((m) => (
              <div className={`msg msg-${m.role}`} key={m.id}>
                <div className="msg-role">{ROLE_LABEL[m.role] ?? m.role}</div>
                <div className="msg-body">{m.content}</div>
              </div>
            ))}
            {events.length > 0 ? (
              <details className="raw-details">
                <summary>查看 {events.length} 条原始响应 / 事件（已脱敏）</summary>
                {events.map((m) => <pre key={m.id}>{m.content}</pre>)}
              </details>
            ) : null}
          </div>

          <div className="home-block-head" style={{ marginTop: 34 }}>
            <h2 className="home-block-title">交付物</h2>
            <button
              className="home-link"
              onClick={() => download(`session-${activeSession.id}.json`, JSON.stringify({ session: activeSession, artifacts }, null, 2), 'application/json')}
            >
              导出会话 JSON
            </button>
          </div>
          {artifacts.length === 0 ? (
            <p className="home-empty">本次运行还没有产物。Agent 必须通过 artifact.write 真实写入才会出现在这里。</p>
          ) : artifacts.map((a) => (
            <div className="home-row" key={a.id}>
              <div className="home-row-main">
                <div className="home-row-name">{a.name}</div>
                <div className="home-row-meta">{a.format} · {a.content.length} 字符 · {new Date(a.updatedAt).toLocaleString('zh-CN')}</div>
              </div>
              <button
                className="home-row-action"
                onClick={() => download(a.name.includes('.') ? a.name : `${a.name}.${extensionForFormat(a.format)}`, a.content, mimeForFormat(a.format))}
              >
                下载 →
              </button>
            </div>
          ))}
        </section>
      ) : null}

      <div className="home-links">
        <button className="home-link" onClick={() => navigate('sessions')}>全部会话</button>
        <button className="home-link" onClick={() => navigate('providers')}>配置我的 AI 模型</button>
        <button className="home-link" onClick={() => navigate('vault')}>密钥保险库</button>
        <button className="home-link" onClick={() => navigate('account')}>登录</button>
        <button className="home-link" onClick={() => navigate('settings')}>设置</button>
      </div>

      <div className="home-status">
        本机数据 · {sessions.length} 个会话 · {providers.length} 个模型 · {TOOL_REGISTRY.length} 个可用工具 · {apiOnline ? 'Worker 已连接' : 'Worker 未连接'}
      </div>

      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">最近会话</h2>
          <button className="home-link" onClick={() => navigate('sessions')}>全部 →</button>
        </div>
        {sessions.length === 0 ? (
          <p className="home-empty">还没有会话。在上方写下任务，确认调用信息后就会创建一个真实会话。</p>
        ) : sessions.slice(0, 4).map((s) => (
          <div className="home-row" key={s.id}>
            <div className="home-row-main">
              <div className="home-row-name">{s.title} <span className="faint" style={{ fontSize: 11, fontWeight: 400 }}>{STATE_LABEL[s.state]}</span></div>
              <div className="home-row-meta">{s.id} · {s.steps.length} 步 · {new Date(s.updatedAt).toLocaleString('zh-CN')}</div>
            </div>
            <button className="home-row-action" onClick={() => openSession(s.id)}>查看 →</button>
          </div>
        ))}
      </section>

      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">我的 AI 模型</h2>
          <button className="home-link" onClick={() => navigate('providers')}>管理 →</button>
        </div>
        {providers.length === 0 ? (
          <p className="home-empty">尚未配置模型。SOL AI 不内置任何人的 Key，也不替其他用户付费；添加你自己的接口后才能发起真实调用。</p>
        ) : providers.slice(0, 4).map((p) => (
          <div className="home-row" key={p.id}>
            <div className="home-row-main">
              <div className="home-row-name">
                {p.name}
                {p.lastTest?.code === 'CONNECTION_OK' ? <span className="faint" style={{ fontSize: 11, fontWeight: 400 }}>已验证</span> : null}
              </div>
              <div className="home-row-meta">{p.baseUrl || '(未填写 Base URL)'} · {p.modelId || '(未填写 Model ID)'} · {protocolLabel(p.protocol)}</div>
            </div>
            <button className="home-row-action" onClick={() => navigate('providers')}>编辑 →</button>
          </div>
        ))}
      </section>

      <section className="home-block">
        <div className="home-block-head">
          <h2 className="home-block-title">Agent 可用工具</h2>
          <span className="home-block-more">{TOOL_REGISTRY.length} 个真实本地工具</span>
        </div>
        {TOOL_REGISTRY.map((t) => (
          <div className="home-row" key={t.id}>
            <div className="home-row-main">
              <div className="home-row-name mono" style={{ fontSize: 12 }}>{t.id}</div>
              <div className="home-row-meta" style={{ whiteSpace: 'normal' }}>{t.description}</div>
            </div>
          </div>
        ))}
      </section>

      <div className="home-foot">
        SOL AI 是支持自带 API Key 的工作 Agent：模型、密钥、会话与产物都在你自己的浏览器里。
        登录与云端同步尚未启用，入口已保留。浏览器本地加密不等于绝对安全；完整说明见仓库 docs/SECURITY.md 与 docs/AGENT.md。
      </div>
    </div>
  );
}
