/**
 * BYOK vault cryptography — Web Crypto API only.
 *
 *   password ──PBKDF2/SHA-256 (310k iterations, random 16-byte salt)──▶ AES-256-GCM key
 *   payload  ──AES-GCM (random 12-byte IV)──▶ ciphertext
 *
 * Nothing is ever written to localStorage in plaintext. The encrypted blob
 * lives in IndexedDB. The decrypted secrets live ONLY in memory and are
 * discarded on lock/reload.
 *
 * SECURITY NOTE: this is protection for a browser-local vault against casual
 * inspection, NOT absolute security. Any code running in the page origin
 * (including XSS or a malicious extension) can read unlocked memory.
 * See docs/SECURITY.md — do not market this as "military grade" or "unhackable".
 */

export const VAULT_FORMAT = 'sol-ai-vault' as const;
export const VAULT_VERSION = 1 as const;
export const PBKDF2_ITERATIONS = 310_000;

export interface VaultFile {
  format: typeof VAULT_FORMAT;
  version: typeof VAULT_VERSION;
  kdf: { name: 'PBKDF2'; hash: 'SHA-256'; iterations: number; salt: string };
  cipher: { name: 'AES-GCM'; iv: string; ciphertext: string };
  createdAt: string;
  updatedAt: string;
}

export type VaultErrorCode =
  | 'INVALID_PASSWORD'
  | 'CORRUPT_VAULT'
  | 'UNSUPPORTED_VERSION'
  | 'CRYPTO_UNAVAILABLE'
  | 'EMPTY_PASSWORD';

export class VaultError extends Error {
  constructor(public readonly code: VaultErrorCode, message?: string) {
    super(message ?? code);
    this.name = 'VaultError';
  }
}

function subtle(): SubtleCrypto {
  const c = globalThis.crypto;
  if (!c || !c.subtle) throw new VaultError('CRYPTO_UNAVAILABLE', 'Web Crypto API is unavailable (secure context required).');
  return c.subtle;
}

export function randomBytes(length: number): Uint8Array {
  const out = new Uint8Array(length);
  globalThis.crypto.getRandomValues(out);
  return out;
}

export function toBase64(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i] as number);
  return btoa(binary);
}

export function fromBase64(value: string): Uint8Array {
  const binary = atob(value);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}

export function newId(prefix = ''): string {
  const bytes = randomBytes(16);
  // UUID-ish, no external dependency
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${prefix}${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

async function deriveKey(password: string, salt: Uint8Array, iterations: number): Promise<CryptoKey> {
  const base = await subtle().importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveKey']);
  return subtle().deriveKey(
    { name: 'PBKDF2', salt: salt as BufferSource, iterations, hash: 'SHA-256' },
    base,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

export interface VaultEncryptOptions {
  iterations?: number;
  now?: string;
}

/** Encrypt an arbitrary JSON-serialisable payload into a portable vault blob. */
export async function encryptVault<T>(
  password: string,
  payload: T,
  options: VaultEncryptOptions = {},
): Promise<VaultFile> {
  if (!password) throw new VaultError('EMPTY_PASSWORD');
  const iterations = options.iterations ?? PBKDF2_ITERATIONS;
  const salt = randomBytes(16);
  const iv = randomBytes(12);
  const key = await deriveKey(password, salt, iterations);
  const plaintext = new TextEncoder().encode(JSON.stringify(payload));
  const ciphertext = await subtle().encrypt({ name: 'AES-GCM', iv: iv as BufferSource }, key, plaintext as BufferSource);
  const now = options.now ?? new Date().toISOString();
  return {
    format: VAULT_FORMAT,
    version: VAULT_VERSION,
    kdf: { name: 'PBKDF2', hash: 'SHA-256', iterations, salt: toBase64(salt) },
    cipher: { name: 'AES-GCM', iv: toBase64(iv), ciphertext: toBase64(new Uint8Array(ciphertext)) },
    createdAt: now,
    updatedAt: now,
  };
}

/** Decrypt + authenticate. AES-GCM auth failure => wrong password OR tampered blob. */
export async function decryptVault<T>(password: string, file: VaultFile): Promise<T> {
  if (!password) throw new VaultError('EMPTY_PASSWORD');
  if (file?.format !== VAULT_FORMAT) throw new VaultError('CORRUPT_VAULT', 'Unrecognised vault format.');
  if (file.version !== VAULT_VERSION) throw new VaultError('UNSUPPORTED_VERSION', `Vault version ${String(file.version)} is not supported.`);
  try {
    const salt = fromBase64(file.kdf.salt);
    const iv = fromBase64(file.cipher.iv);
    const key = await deriveKey(password, salt, file.kdf.iterations);
    const plain = await subtle().decrypt(
      { name: 'AES-GCM', iv: iv as BufferSource },
      key,
      fromBase64(file.cipher.ciphertext) as BufferSource,
    );
    return JSON.parse(new TextDecoder().decode(plain)) as T;
  } catch (error) {
    if (error instanceof VaultError) throw error;
    throw new VaultError('INVALID_PASSWORD', 'Unlock failed: incorrect password or the encrypted data was modified.');
  }
}

/** Rotate password without ever exposing plaintext outside memory. */
export async function reencryptVault<T>(oldPassword: string, newPassword: string, file: VaultFile): Promise<VaultFile> {
  const payload = await decryptVault<T>(oldPassword, file);
  const rotated = await encryptVault(newPassword, payload);
  return { ...rotated, createdAt: file.createdAt };
}

/** Structural validation for imported backups, before any crypto work. */
export function isVaultFile(value: unknown): value is VaultFile {
  if (!value || typeof value !== 'object') return false;
  const v = value as Partial<VaultFile>;
  return (
    v.format === VAULT_FORMAT &&
    v.version === VAULT_VERSION &&
    typeof v.kdf?.salt === 'string' &&
    typeof v.kdf?.iterations === 'number' &&
    typeof v.cipher?.iv === 'string' &&
    typeof v.cipher?.ciphertext === 'string'
  );
}
