/**
 * SOL AI Work Agent — domain types (v1, local-only).
 *
 * Design rules:
 * - A session is a real, persisted task run. Nothing in here is a mock.
 * - `providerId` is ALWAYS an explicit user choice. The agent never silently
 *   switches models and never falls back to a built-in model.
 * - Steps are an audit trail of REAL model calls and REAL tool executions.
 *   No synthetic "thinking" progress is ever generated.
 * - Every string that is persisted passes through secret redaction first.
 */

import type { TestOutcomeCode } from './types';

export type AgentRunState = 'idle' | 'running' | 'succeeded' | 'failed' | 'cancelled';

export type MessageRole = 'user' | 'assistant' | 'tool' | 'system' | 'event';

/** Metadata for a message produced by a genuine upstream call. */
export interface AgentCallMeta {
  providerId: string;
  modelId: string;
  protocol: string;
  httpStatus?: number;
  latencyMs?: number;
  transport?: 'worker' | 'direct';
  errorCode?: TestOutcomeCode;
}

export interface AgentMessage {
  id: string;
  role: MessageRole;
  content: string;
  createdAt: string;
  /** Set for tool results so the loop can label the feedback turn. */
  toolId?: string;
  /** Absent for local events and tool results. */
  call?: AgentCallMeta;
}

export type StepKind = 'model' | 'tool' | 'final' | 'error' | 'cancel';

export interface AgentStep {
  index: number;
  kind: StepKind;
  at: string;
  summary: string;
  /** Already redacted and truncated before persistence. */
  detail?: string;
  ok: boolean;
  latencyMs?: number;
  toolId?: string;
  transport?: 'worker' | 'direct';
  httpStatus?: number;
}

export type ArtifactFormat = 'markdown' | 'json' | 'text';

export interface AgentArtifact {
  id: string;
  sessionId: string;
  name: string;
  format: ArtifactFormat;
  content: string;
  createdAt: string;
  updatedAt: string;
}

export interface CostEstimate {
  /** false = provider has no verified price rule. Never invent a price. */
  known: boolean;
  text: string;
}

export interface AgentSession {
  id: string;
  title: string;
  /** The original user task. Never rewritten by the model. */
  goal: string;
  /** Explicit user-selected provider. Empty = no model chosen yet. */
  providerId: string;
  systemPrompt: string;
  messages: AgentMessage[];
  steps: AgentStep[];
  state: AgentRunState;
  maxSteps: number;
  createdAt: string;
  updatedAt: string;
  lastError?: string;
  estimate?: CostEstimate;
}

/**
 * The structured protocol the model MUST follow for every turn.
 * Parsed and validated locally; a non-conforming response is REJECTED,
 * never silently repaired into a fake success.
 */
export interface AgentAction {
  thought: string;
  tool?: { id: string; args: Record<string, unknown> };
  final?: string;
}

export const DEFAULT_MAX_STEPS = 8;
export const MAX_AGENT_STEPS = 20;
export const AGENT_PROTOCOL_VERSION = 1;

/** Only safe, single-segment artifact names. No paths, no traversal. */
export function normalizeArtifactName(input: string): string {
  const name = String(input ?? '').trim();
  if (!name) throw new Error('产物名称不能为空。');
  if (name.length > 120) throw new Error('产物名称不能超过 120 个字符。');
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(name) || name.includes('..')) {
    throw new Error('产物名称只能包含字母、数字、点、下划线和连字符，且不能以点开头。');
  }
  return name;
}

export function mimeForFormat(format: ArtifactFormat): string {
  return format === 'json' ? 'application/json' : format === 'markdown' ? 'text/markdown' : 'text/plain';
}

export function extensionForFormat(format: ArtifactFormat): string {
  return format === 'json' ? 'json' : format === 'markdown' ? 'md' : 'txt';
}
