/**
 * Local persistence for Work Agent sessions and artifacts.
 *
 * SECURITY: the model can accidentally echo an upstream response that contains
 * a key. Every string is redacted (including keys currently held by the
 * unlocked vault) BEFORE it is written to IndexedDB. Nothing here is a secret
 * store — keys live only in the encrypted vault and in memory while unlocked.
 *
 * NOTE: legacy `KV.projects` records (video-studio era) are intentionally
 * left untouched. They are neither migrated nor deleted, just not surfaced.
 */

import { redactSecrets } from './adapter';
import { newId } from './crypto';
import { idbGet, idbSet, KV, STORE_KV } from './idb';
import { vault } from './vault';
import {
  DEFAULT_MAX_STEPS,
  MAX_AGENT_STEPS,
  normalizeArtifactName,
  type AgentArtifact,
  type AgentMessage,
  type AgentSession,
  type AgentStep,
  type ArtifactFormat,
} from './agentTypes';

const MAX_STEP_DETAIL = 2000;

/** Plaintext secrets currently visible in memory. Empty when the vault is locked. */
function currentSecrets(): string[] {
  const out: string[] = [];
  try {
    for (const id of vault.storedProviderIds) {
      const secret = vault.getSecret(id);
      if (secret?.apiKey) out.push(secret.apiKey);
      for (const value of Object.values(secret?.extraHeaders ?? {})) {
        if (typeof value === 'string' && value.length >= 6) out.push(value);
      }
    }
  } catch {
    /* vault locked / unavailable — nothing to redact beyond pattern matching */
  }
  return out;
}

export function sanitize(text: string, secrets = currentSecrets()): string {
  return redactSecrets(text, secrets);
}

function cleanMessage(m: AgentMessage, secrets: string[]): AgentMessage {
  return { ...m, content: sanitize(m.content, secrets) };
}

function cleanStep(s: AgentStep, secrets: string[]): AgentStep {
  return {
    ...s,
    summary: sanitize(s.summary, secrets),
    ...(s.detail ? { detail: sanitize(s.detail, secrets).slice(0, MAX_STEP_DETAIL) } : {}),
  };
}

function cleanSession(session: AgentSession, secrets: string[]): AgentSession {
  return {
    ...session,
    title: sanitize(session.title, secrets),
    goal: sanitize(session.goal, secrets),
    systemPrompt: sanitize(session.systemPrompt, secrets),
    messages: session.messages.map((m) => cleanMessage(m, secrets)),
    steps: session.steps.map((s) => cleanStep(s, secrets)),
    ...(session.lastError ? { lastError: sanitize(session.lastError, secrets).slice(0, MAX_STEP_DETAIL) } : {}),
  };
}

function cleanArtifact(a: AgentArtifact, secrets: string[]): AgentArtifact {
  return { ...a, name: a.name, content: sanitize(a.content, secrets) };
}

export async function listSessions(): Promise<AgentSession[]> {
  const items = (await idbGet<AgentSession[]>(STORE_KV, KV.sessions)) ?? [];
  return [...items].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export async function getSession(id: string): Promise<AgentSession | undefined> {
  return (await listSessions()).find((s) => s.id === id);
}

export interface CreateSessionInput {
  goal: string;
  providerId: string;
  title?: string;
  systemPrompt?: string;
  maxSteps?: number;
}

export function sessionTitle(goal: string): string {
  const first = goal.trim().split('\n').map((l) => l.trim()).find(Boolean) ?? '未命名任务';
  return first.length > 28 ? `${first.slice(0, 28)}…` : first;
}

export async function createSession(input: CreateSessionInput): Promise<AgentSession> {
  const now = new Date().toISOString();
  const session: AgentSession = {
    id: newId('ses_'),
    title: input.title?.trim() || sessionTitle(input.goal),
    goal: input.goal,
    providerId: input.providerId,
    systemPrompt: input.systemPrompt ?? '',
    messages: [],
    steps: [],
    state: 'idle',
    maxSteps: Math.min(Math.max(input.maxSteps ?? DEFAULT_MAX_STEPS, 1), MAX_AGENT_STEPS),
    createdAt: now,
    updatedAt: now,
  };
  const all = await listSessions();
  await idbSet(STORE_KV, KV.sessions, [cleanSession(session, currentSecrets()), ...all]);
  return session;
}

export async function saveSession(session: AgentSession): Promise<void> {
  const all = await listSessions();
  const next: AgentSession = cleanSession(
    { ...session, updatedAt: new Date().toISOString() },
    currentSecrets(),
  );
  const index = all.findIndex((s) => s.id === session.id);
  if (index === -1) all.unshift(next);
  else all[index] = next;
  await idbSet(STORE_KV, KV.sessions, all);
}

/** Deletes the session AND all artifacts it owns. */
export async function deleteSession(id: string): Promise<void> {
  const [sessions, artifacts] = await Promise.all([listSessions(), listArtifacts()]);
  await Promise.all([
    idbSet(STORE_KV, KV.sessions, sessions.filter((s) => s.id !== id)),
    idbSet(STORE_KV, KV.artifacts, artifacts.filter((a) => a.sessionId !== id)),
  ]);
}

export async function listArtifacts(sessionId?: string): Promise<AgentArtifact[]> {
  const items = (await idbGet<AgentArtifact[]>(STORE_KV, KV.artifacts)) ?? [];
  return (sessionId ? items.filter((a) => a.sessionId === sessionId) : [...items]).sort(
    (a, b) => b.updatedAt.localeCompare(a.updatedAt),
  );
}

export async function getArtifact(sessionId: string, name: string): Promise<AgentArtifact | undefined> {
  const safe = normalizeArtifactName(name);
  return (await listArtifacts(sessionId)).find((a) => a.name === safe);
}

export async function putArtifact(
  sessionId: string,
  name: string,
  content: string,
  format: ArtifactFormat = 'markdown',
): Promise<AgentArtifact> {
  const safe = normalizeArtifactName(name);
  const now = new Date().toISOString();
  const all = await listArtifacts();
  const existing = all.find((a) => a.sessionId === sessionId && a.name === safe);
  const artifact: AgentArtifact = {
    id: existing?.id ?? newId('art_'),
    sessionId,
    name: safe,
    format,
    content,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
  };
  const next = existing
    ? all.map((a) => (a.id === existing.id ? cleanArtifact(artifact, currentSecrets()) : a))
    : [cleanArtifact(artifact, currentSecrets()), ...all];
  await idbSet(STORE_KV, KV.artifacts, next);
  return artifact;
}

export async function removeArtifact(sessionId: string, name: string): Promise<boolean> {
  const safe = normalizeArtifactName(name);
  const all = await listArtifacts();
  const target = all.find((a) => a.sessionId === sessionId && a.name === safe);
  if (!target) return false;
  await idbSet(STORE_KV, KV.artifacts, all.filter((a) => a.id !== target.id));
  return true;
}
