import { useApp } from '../state/AppContext';
import { Callout, Pill, SectionHead } from '../components/ui';
import { getAuthAdapter } from '../lib/authAdapter';

export function Account(): JSX.Element {
  const { me, apiOnline, vaultExists, sessions } = useApp();
  const adapter = getAuthAdapter();

  return (
    <>
      <div className="page-head">
        <h1 className="page-title display">账户与登录</h1>
        <p className="page-lede">登录入口已保留。当前版本不实现登录，也不伪造任何登录态、用户资料或云端同步状态。</p>
      </div>

      <Callout neutral>
        <strong>登录系统尚未启用。</strong>你现在以「访客本地模式」使用 SOL AI：模型配置、密钥保险库、会话与产物
        全部保存在这台设备的浏览器里，不会上传，也不会与其他用户共享。需要云端同步、多用户隔离与邀请测试时，
        才需要接入认证。下面的三个入口是预留位置，点击不会发起任何请求。
      </Callout>

      <SectionHead num="01" title="登录方式（预留）" aside="Disabled by design" />
      {adapter.entrances().map((e) => (
        <div className="row" key={e.id}>
          <div className="row-main">
            <div className="row-name">{e.label} <Pill tone="warn">未启用</Pill></div>
            <div className="row-meta">{e.note}</div>
          </div>
          <button
            className="btn btn-sm"
            disabled={!e.enabled}
            aria-disabled={!e.enabled}
            onClick={e.enabled ? () => void adapter.beginLogin(e.id) : undefined}
          >
            {e.enabled ? '登录' : '不可用'}
          </button>
        </div>
      ))}

      <SectionHead num="02" title="当前真实状态" aside="Local guest" />
      <dl className="kv">
        <dt>当前身份</dt><dd>{me ? (me.isGuest ? '访客（Worker 返回的 guest 身份）' : `${me.displayName ?? me.userId} · ${me.tier} · ${me.provider}`) : '访客（本地模式）'}</dd>
        <dt>认证适配器</dt><dd className="mono">{adapter.id} · {adapter.label}</dd>
        <dt>Worker 连接</dt><dd>{apiOnline ? '已连接' : '未连接（静态站点，本机工作台仍可用）'}</dd>
        <dt>密钥保险库</dt><dd>{vaultExists ? '已创建（在本机）' : '未创建'}</dd>
        <dt>本机会话</dt><dd>{sessions.length} 个</dd>
        <dt>云端同步</dt><dd>未启用</dd>
        <dt>手机号验证</dt><dd>不计划强制要求</dd>
      </dl>

      <SectionHead num="03" title="后续接入约定" aside="Replaceable auth" />
      <div className="notice" style={{ marginTop: 0, borderTop: 0, paddingTop: 0 }}>
        认证是可替换的适配层，不与业务逻辑绑定。接入时只需实现统一的身份解析接口，
        返回 <span className="mono">userId / workspaceId / tier</span>，
        再由服务端把所有数据查询强制限定在租户范围内；前端这里只需替换按钮的跳转逻辑。
        会员等级与配额字段已预留，支付与订阅在第一版不开发。
        详细说明见仓库 <span className="mono">docs/AGENT.md</span> 与 <span className="mono">docs/SECURITY.md</span>。
      </div>
    </>
  );
}
